L5_1.m_Face = "UNIT_LAUGH"
L5_1.m_CharStrID = "CHILDREN_BARCODE_TWO_NULL"
L5_1.m_Pos = "R_M_I"
L5_1.m_Talk_KOREA = "아인, 이것 봐~ 나 엄청 작은 물고기를 잡았어~"
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "アイン、みてみて～！　ぼく、すっごく小さいお魚さんを捕まえたの～！"
L5_1.m_Talk_ENG = "Look, Eins! I caught a tiny teeny fish!"
L5_1.m_Talk_TWN = "艾茵你看～我抓到一條超小的魚欸～"
L5_1.m_Talk_THA = "ดูดิไอนส์! เค้าจับปลาตัวเล็กได้ด้วยอ้ะ!"
L5_1.m_Talk_VTN = "Nhìn kìa, Eins! Em bắt được một con cá nhỏ xíu!"
L5_1.m_Talk_SCN = "艾因，你看这个~我抓到了一只超级小的鱼~"
L5_1.m_Talk_DEU = "Schau, Eins! Ich habe einen winzigen Fisch gefangen!"
L5_1.m_Talk_FRA = "Regarde, Eins ! J'ai attrapé un petit poisson !"
L6_1 = {}
L6_1.m_CutScenKey_Talk = "HORIZON_ACT5_INTERLUDE1@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 3500501
L6_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "CHILDREN_BARCODE_ONE_NULL"
L6_1.m_Pos = "L"
L6_1.m_Crash = 10
L6_1.m_Talk_KOREA = "흥, 겨우 그 정도 가지고? 내가 잡은 물고기는 엄청엄청 작거든?"
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "ふん、それくらいで？　あたしが捕まえたお魚のほうがもっともっと小さいよ？"
L6_1.m_Talk_ENG = "Hmph! That's nothing! I caught a tiny teeny weeny fish!"
L6_1.m_Talk_TWN = "拜託～才這樣喔？我抓到的魚才是宇宙無敵小呢！"
L6_1.m_Talk_THA = "เฮอะ! ไม่เห็นจะน่าตื่นเต้น! ปลาที่เค้าจับได้อะตัวเล็กกว่าอีก!"
L6_1.m_Talk_VTN = "Hừm! Bình thường! Chị đã bắt được một con cá weeny nhỏ xíu!"
L6_1.m_Talk_SCN = "哼，才那种程度而已？我抓到的鱼才是超级超级小。"
L6_1.m_Talk_DEU = "Hmpf! Das ist gar nichts! Ich habe einen winzig winzigen Fisch gefangen!"
L6_1.m_Talk_FRA = "Pff ! C'est rien du tout ça ! Moi j'ai attrapé un poisson vraiment minuscule !"
L7_1 = {}
L7_1.m_CutScenKey_Talk = "HORIZON_ACT5_INTERLUDE1@7#Talk"
L7_1.m_CutScenProcessKey = 7
