L7_1.m_Pos = "L"
L7_1.m_Crash = 20
L7_1.m_Talk_KOREA = "짜잔. 어때? 손바닥에 들어올 만큼 작지?"
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "ジャジャーン！　どう？　手のひらよりも小さいでしょ？"
L7_1.m_Talk_ENG = "Tah-dah. See? It's small enough to fit in my palm!"
L7_1.m_Talk_TWN = "鏘鏘～怎麼樣？小到我可以一手掌握喔！"
L7_1.m_Talk_THA = "แถ่น-แท้น เห็นมั้ย? เล็กพอดีมือเค้าเลยอ้ะ!"
L7_1.m_Talk_VTN = "Tah-dah. Xem này? Nó đủ nhỏ để nằm gọn trong lòng bàn tay của chị!"
L7_1.m_Talk_SCN = "你看。怎么样？比手掌还小吧？"
L7_1.m_Talk_DEU = "Tada! Na? Er ist kleiner als meine Handfläche!"
L7_1.m_Talk_FRA = "Tadaa ! Tu vois ? Il est si petit qu'il rentre dans la paume de ma main !"
L8_1 = {}
