L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "うわあ～！　じゃあ、ぼくはもっともっともーっと小さいお魚さんを捕まえる！"
L8_1.m_Talk_ENG = "Wow! Then I'm gonna catch a tiny teeny weeny itsy-bitsy fish!"
