L8_1.m_Talk_THA = "โอ้โห! งั้นเดี๋ยวเค้าจะจับปลาตัวเล็กตัวน้อยตะนิดตะหน่อยนะ!"
L8_1.m_Talk_VTN = "Ồ! Vậy em sẽ bắt một con cá nhỏ xíu béo ngậy ngon lành."
L8_1.m_Talk_SCN = "哇啊~那我就要抓一只超级超级超级小的鱼。"
L8_1.m_Talk_DEU = "Wow! Dann fange ich jetzt einen winzig winzig winzigen Fisch!"
