L16_1.m_Talk_KOREA = "<color=#ffd34c>잔여 동력 5.7%. 정보 오염에 대비하기 위한 동력이 확보되었습니다.</color>"
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "<color=#ffd34c>残余エネルギー5.7％。情報汚染に備えるためのエネルギーを確保しました。</color>"
L16_1.m_Talk_ENG = "<color=#ffd34c>Current remaining power is at 5.7%. Adequate power secured to guard against data corruption.</color>"
L16_1.m_Talk_TWN = "<color=#ffd34c>剩餘動能 5.7%。預防情報污染的動能無虞。</color>"
L16_1.m_Talk_THA = "<color=#ffd34c>ระดับพลังงานคงเหลืออยู่ที่ 5.7% เพียงพอจะป้องกันไม่ให้ข้อมูลถูกคอร์รัปชั่นได้อย่างปลอดภัย</color>"
L16_1.m_Talk_VTN = "<color=#ffd34c>Công suất còn lại hiện tại là 5,7%. Đủ năng lượng được bảo đảm để bảo vệ chống lại ăn mòn dữ liệu.</color>"
L16_1.m_Talk_SCN = "<color=#ffd34c>剩余动力5.7%。尚有抵御信息污染的动力。</color>"
L16_1.m_Talk_DEU = "<color=#ffd34c>Die aktuelle Restleistung beträgt 5,7 %. Ausreichender Antrieb zum Schutz vor Datenkorruption gesichert.</color>"
L16_1.m_Talk_FRA = "<color=#ffd34c>Alimentation restante : 5,7 %. Énergie suffisante pour assurer la protection contre la corruption de données.</color>"
