L17_1.m_Talk_THA = "<color=#ffd34c>เปลี่ยนเป็นเซฟโหมดเพื่อคำนวณความมีประสิทธิภาพของพลังงานใหม่</color>"
L17_1.m_Talk_VTN = "<color=#ffd34c>Chuyển sang chế độ an toàn để hiệu chỉnh lại hiệu quả sử dụng điện.</color>"
L17_1.m_Talk_SCN = "<color=#ffd34c>为了调整动力效能，将转换为安全模式。</color>"
L17_1.m_Talk_DEU = "<color=#ffd34c>In den abgesicherten Modus wechseln, um die Antriebseffizienz zu kalibrieren.</color>"
