L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "ホントだ！　あたしが一番先に知らせよーっと！"
L22_1.m_Talk_ENG = "Really? Then I'm gonna tell her first!"
L22_1.m_Talk_TWN = "真的嗎？那我要趕快去跟姊姊說～"
L22_1.m_Talk_THA = "จิงอะ? งั้นเค้าบอกเธอก่อนนะ!"
L22_1.m_Talk_VTN = "Có thật không? Vậy thì chị sẽ nói với cô ấy trước!"
L22_1.m_Talk_SCN = "真的吗？那我要先去通知大家~"
L22_1.m_Talk_DEU = "Echt? Dann will ich als Erste Bescheid sagen!"
L22_1.m_Talk_FRA = "Vraiment ? Dans ce cas, c'est moi qui vais lui dire en premier !"
