L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "えっ、ぼくもいくー！"
L25_1.m_Talk_ENG = "Ooh, me too!"
L25_1.m_Talk_TWN = "喔！那茨粨也要去跟姊姊說～"
L25_1.m_Talk_THA = "เอ๊า เค้าด้วยสิ?"
L25_1.m_Talk_VTN = "Ooh, em cũng vậy!"
