L28_1 = {}
L28_1.m_CutScenKey_Talk = "HORIZON_ACT5_INTERLUDE1@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 3500501
L28_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_DESPAIR"
L28_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L28_1.m_Pos = "C"
L28_1.m_Talk_KOREA = "여기는……. 대기가 존재하는 것으로 보아 바다 밑바닥은 아니군요."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "ここは……大気が存在することから海の底ではなさそうですね。"
L28_1.m_Talk_ENG = "I take it… that I'm no longer on the seabed, judging by the presence of a breathable atmosphere."
L28_1.m_Talk_TWN = "這裡是……有空氣，那應該不是海底。"
L28_1.m_Talk_THA = "เดาว่า... ฉันไม่ได้อยู่ก้นทะเลแล้วสินะคะ ดูจากบรรยากาศที่หายใจได้นี่"
L28_1.m_Talk_VTN = "Mình hiểu rằng… mình không còn ở dưới đáy biển, dựa trên điều kiện là có một bầu không khí thoáng khí."
L28_1.m_Talk_SCN = "这里……存在空气，所以应该不是海底。"
L28_1.m_Talk_DEU = "Hier ... gibt es eine Atmosphäre. Daraus schließe ich, dass ich mich nicht mehr auf dem Meeresboden befinde."
L28_1.m_Talk_FRA = "À en juger par la présence d'une atmosphère respirable, j'en déduis que je ne me trouve plus sur le plancher océanique."
L29_1 = {}
L29_1.m_CutScenKey_Talk = "HORIZON_ACT5_INTERLUDE1@29#Talk"
L29_1.m_CutScenProcessKey = 29
L29_1.m_CutScenID = 3500501
L29_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_IDLE"
L29_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L29_1.m_Pos = "C"
L29_1.m_Talk_KOREA = "혹시 휴먼들이 얘기하는 아틀란티스입니까?"
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "もしやここは、ヒューマンの間で有名なアトランティスでしょうか？"
L29_1.m_Talk_ENG = "Is this perhaps the legendary Atlantis that humans speak of?"
L29_1.m_Talk_TWN = "是人類說的亞特蘭堤斯嗎？"
L29_1.m_Talk_THA = "นี่คือแอตแลนติสในตำนานที่มนุษย์พูดถึงกันรึเปล่าคะ?"
L29_1.m_Talk_VTN = "Đây có lẽ nào là Atlantis huyền thoại mà con người nói đến chăng?"
L29_1.m_Talk_SCN = "难道是人们说的亚特兰蒂斯吗？"
L29_1.m_Talk_DEU = "Ist hier vielleicht das Atlantis, von dem die Menschen sprechen?"
L29_1.m_Talk_FRA = "Serais-je dans la légendaire Atlantide, dont les humains parlent tant ?"
