L31_1 = {}
L31_1.m_CutScenKey_Talk = "HORIZON_ACT5_INTERLUDE1@31#Talk"
L31_1.m_CutScenProcessKey = 31
L31_1.m_CutScenID = 3500501
L31_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L31_1.m_Pos = "C"
L31_1.m_Talk_KOREA = "죄송해요. 아틀란티스는 아니지만……. 바닷속보다는 안전한 곳이에요."
L31_1.m_fTalkTime = 0.03
L31_1.m_Talk_JPN = "すみません。アトランティスではありませんが……海の中よりは安全な場所だと思います。"
L31_1.m_Talk_ENG = "Sorry. It's no Atlantis… but it sure is much safer than the bottom of the ocean."
L31_1.m_Talk_TWN = "抱歉，這裡不是亞特蘭堤斯……但是比海裡安全的地方。"
L31_1.m_Talk_THA = "เสียใจด้วยนะคะ ที่นี่ไม่ใช่แอตแลนติสหรอก แต่ก็ปลอดภัยกว่าก้นทะเลค่ะ"
L31_1.m_Talk_VTN = "Xin lỗi. Đây không phải là Atlantis… nhưng chắc chắn nó an toàn hơn nhiều so với đáy đại dương."
L31_1.m_Talk_SCN = "抱歉。这里不是亚特兰蒂斯……但比深海安全一些。"
L31_1.m_Talk_DEU = "Sorry, hier ist nicht Atlantis ... Aber hier sind Sie sicherer als im Meer."
L31_1.m_Talk_FRA = "Désolée, ce n'est pas l'Atlantide... Mais c'est bien plus sûr ici que sous les eaux."
L32_1 = {}
L32_1.m_CutScenKey_Talk = "HORIZON_ACT5_INTERLUDE1@32#Talk"
L32_1.m_CutScenProcessKey = 32
L32_1.m_CutScenID = 3500501
L32_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L32_1.m_Pos = "C"
L32_1.m_Crash = 15
L32_1.m_Talk_KOREA = "저기……. 몸은 좀 괜찮으세요?"
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "あの……具合はいかがですか？"
L32_1.m_Talk_ENG = "So, um… How are you feeling?"
L32_1.m_Talk_TWN = "請問……你的身體還好嗎？"
L32_1.m_Talk_THA = "ว่าแต่... คุณเป็นยังไงบ้างคะ?"
L32_1.m_Talk_VTN = "Vậy, ừm… Cô cảm thấy thế nào?"
L32_1.m_Talk_SCN = "你……身体没事吗？"
L32_1.m_Talk_DEU = "Hey ... wie geht es Ihnen?"
L32_1.m_Talk_FRA = "Alors... Comment vous sentez-vous ?"
L33_1 = {}
L33_1.m_CutScenKey_Talk = "HORIZON_ACT5_INTERLUDE1@33#Talk"
L33_1.m_CutScenProcessKey = 33
L33_1.m_CutScenID = 3500501
L33_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L33_1.m_Pos = "C"
L33_1.m_Talk_KOREA = "……생체 정보. 확인."
L33_1.m_fTalkTime = 0.03
L33_1.m_Talk_JPN = "……生体情報、確認。"
L34_1 = "Biometrics… identified."
L33_1.m_Talk_ENG = L34_1
L34_1 = "……生物資訊確認。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ยืนยันข้อมูล... ชีวมาตรแล้ว"
L33_1.m_Talk_THA = L34_1
L34_1 = "Sinh trắc học… được xác định."
L33_1.m_Talk_VTN = L34_1
L34_1 = "……生物信息，确认完毕。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Biometrische Daten. Erkannt."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Analyse biométrique terminée..."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "HORIZON_ACT5_INTERLUDE1@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3500501
L34_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = "의외로군요. 당신이 저를 바다에서 인양하셨습니까."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "意外ですね。あなたが私を海から引き揚げたのですか？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Things took a rather unexpected turn of events. Did you salvage me from the sea?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "真是意外，是你把我從海裡打撈上來的嗎？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เรื่องราวไม่เป็นไปอย่างที่คิดค่ะ นี่คุณกู้ฉันขึ้นมาจากทะเลเหรอคะ?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Mọi chuyện bất ngờ quá. Cô đã trục vớt tôi từ biển à?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "真是意外。是你把我从海底捞出来的吗？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Wie unerwartet. Haben Sie mich aus dem Meer geborgen?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Les choses ne se sont pas déroulées comme prévu. C'est vous qui m'avez repêchée ?"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
