L37_1 = {}
L38_1 = "HORIZON_ACT5_INTERLUDE1@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3500501
L37_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_DESPAIR"
L37_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L37_1.m_Pos = "R"
L37_1.m_Crash = 10
L38_1 = "아, 네. 혹시나 계속 바닷속에 머물고 싶으셨다면……. 죄송해요."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "あ、はい。もしかしてずっと海の中にいたかったのなら……すみません。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Oh… Yes. Would you have rather stayed there…? I apologize, if that's the case."
L37_1.m_Talk_ENG = L38_1
L38_1 = "嗯，對，還是其實你想繼續待在海裡……不好意思。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "อ๋อ... ค่ะ คุณอยากอยู่ที่นั่นมากกว่ารึเปล่าคะ...? ขออภัยค่ะ แค่ถามเผื่อไว้"
L37_1.m_Talk_THA = L38_1
L38_1 = "Oh... Ừ. Cô muốn ở lại đó à…? Tôi xin lỗi, nếu đúng như vậy."
L37_1.m_Talk_VTN = L38_1
L38_1 = "啊，是的。如果你原来是想一直待在海里的话……那对不起。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Oh, genau. Es tut mir leid, falls Sie lieber weiter im Meer bleiben wollten ..."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Oh, oui. Mais peut-être que vous préfériez rester sous les flots ? Je vous prie de m'excuser si c'est le cas..."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "HORIZON_ACT5_INTERLUDE1@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3500501
L38_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L38_1.m_Pos = "L"
L39_1 = "아닙니다. 진공관께서 이 땅에 탄생하신 이래 우리 기계와 바닷물은 오랜 상극 관계를 이어 왔으니까요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "いいえ。真空管様がこの地に誕生して以来、我々機械と海水は長きにわたり相反する関係でした。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "No need for an apology. Ever since the first great diode existed upon this land, we machines have maintained a notoriously adverse relationship with sea water."
L38_1.m_Talk_ENG = L39_1
L39_1 = "不，自從真空管在這塊土地上誕生後，我們機器和海水就是水火不容的。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ไม่จำเป็นต้องขออภัยหรอกค่ะ นับแต่ไดโอดตัวแรกปรากฏกายขึ้นบนแผ่นดินนี้ จักรกลอย่างเราก็ได้ชื่อว่ามีความสัมพันธ์ที่ไม่ดีกับน้ำทะเลมาตลอด"
L38_1.m_Talk_THA = L39_1
L39_1 = "Không cần xin lỗi. Kể từ khi diode vĩ đại đầu tiên tồn tại trên vùng đất này, máy móc chúng tôi đã duy trì mối quan hệ bất lợi nổi tiếng với nước biển."
L38_1.m_Talk_VTN = L39_1
L39_1 = "否定。从诞生以来，我们机械和海水维持着长久的相克关系。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Nicht doch. Seit die Dioden auf diese Erde herabstiegen, haben wir, die Maschinen, und das Meerwasser eine unvereinbare Beziehung geführt."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Inutile de vous excuser. Depuis que la grande diode a vu le jour sur cette terre, nous les machines avons toujours eu une aversion notoire envers l'eau de mer."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "HORIZON_ACT5_INTERLUDE1@39#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 39
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3500501
L39_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L39_1.m_Pos = "R"
L39_1.m_Crash = 15
L40_1 = "그, 그렇군요. 제가 아직 세상 일은 잘 몰라서……. 죄송해요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "そ、そうだったんですね。まだ世間のことはあまりわかっていなくて……すみません。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "I-I see. I'm not so familiar with how the world works yet… I'm sorry."
L39_1.m_Talk_ENG = L40_1
L40_1 = "原…原來是這樣，我對世界上的事還不是很清楚……不好意思。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "งะ-งั้นเหรอคะ ฉันไม่ค่อยคุ้นหรอกนะคะว่าโลกมันเป็นยังไง... ขอโทษค่ะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "T-tôi biết rồi. Tôi chưa hiểu rõ về cách thế giới vận hành lắm… Tôi xin lỗi."
L39_1.m_Talk_VTN = L40_1
L40_1 = "原、原来如此。我可能对这些常识不太了解……对不起。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "A-ach so. Ich kenne mich nicht so gut in der Welt aus. Verzeihung ..."
L39_1.m_Talk_DEU = L40_1
L40_1 = "J-Je vois. Je ne suis pas encore très familière avec ce monde. Veuillez m'excuser..."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "HORIZON_ACT5_INTERLUDE1@40#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 40
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3500501
L40_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L40_1.m_Pos = "L"
L41_1 = "왜 계속 죄송해합니까, 휴먼."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "なぜずっと謝るのですか、ヒューマン。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Why do you keep apologizing, human?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "人類，你幹嘛一直不好意思？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ทำไมคุณเอาแต่ขอโทษคะมนุษย์?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Tại sao cô cứ xin lỗi mãi thế, con người?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "为什么一直说对不起。人类。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Warum entschuldigen Sie sich die ganze Zeit, Mensch?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Pourquoi vous excusez-vous autant, humaine ?"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "HORIZON_ACT5_INTERLUDE1@41#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 41
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3500501
L41_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L41_1.m_Pos = "L"
L42_1 = "인양 비용을 고려하면 당신은 현재 <color=#ffd34c>갑</color>입니다. 조금 더 세게 나와 주시죠."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "引き揚げ費用を考慮すると、あなたは現在<color=#ffd34c>甲</color>の立場です。もっと強く出てください。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Considering the cost of salvage operations, you're the one with the <color=#ffd34c>clout</color> between us. I must insist you behave more boldly."
L41_1.m_Talk_ENG = L42_1
L42_1 = "考慮到打撈的費用，你現在應該可以算是<color=#ffd34c>債權人</color>，氣勢可以再高張一點。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เมื่อพิจารณาจากค่าเก็บกู้แล้ว คุณเป็นฝ่ายที่<color=#ffd34c>มีอิทธิพลเหนือกว่า</color>นะคะ ฉันขอยืนกรานว่าคุณควรทำตัวให้กล้ากว่านี้ค่ะ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Xem xét chi phí của các hoạt động cứu hộ, cô là người có <color=#ffd34c> tầm ảnh hưởng</color> giữa chúng ta. Tôi phải nhấn mạnh rằng cô nên cư xử mạnh dạn hơn."
L41_1.m_Talk_VTN = L42_1
L42_1 = "如果考虑到打捞费用的话，你现在是<color=#ffd34c>甲方</color>。所以态度可以更强硬一些。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Wenn man die Bergungskosten bedenkt, haben Sie derzeit die <color=#ffd34c>Oberhand</color>. Seien Sie ruhig etwas resoluter."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Si l'on considère le coût de cette opération de sauvetage, c'est vous qui avez la<color=#ffd34c>main haute</color> actuellement. Alors gardez votre sang-froid."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
