L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "CHILDREN_BARCODE_ONE_NULL"
L44_1.m_Pos = "L"
L45_1 = "우리 언니는 나쁜 말 안 해. 교실에 거미가 들어와도 운동장 나무에 데려다 주는 사람이니까."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "お姉ちゃんはとても優しい人なの。教室にクモが入ってきても、庭の木まで移してあげる人なんだから。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Big sis never says anything bad. She's so sweet she'd take a spider to the tree in the school yard if she found one in the classroom."
L44_1.m_Talk_ENG = L45_1
L45_1 = "我姊姊才不是這種人，她連有蜘蛛跑到教室裡，她也會帶到操場的樹上上去放生喔！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "พี่สาวไม่เคยพูดอะไรไม่ดีหรอกค่ะ เธอน่ารักขนาดที่ว่าถ้าเจอแมงมุมในห้องเรียน ก็จะพาไปไว้บนต้นไม้เลยนะ"
L44_1.m_Talk_THA = L45_1
L45_1 = "Chị cả không bao giờ nói điều gì xấu. Chị ấy ngọt ngào đến mức sẽ dắt một con nhện đến cái cây trong sân trường nếu tìm thấy một con trong lớp."
L44_1.m_Talk_VTN = L45_1
L45_1 = "姐姐是不会说坏话的人。就算是教室里进入了一只蜘蛛，也会将它送到操场的树上。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Sie sagt nie etwas Böses. Sie würde sogar eine Spinne zum Baum auf dem Schulhof tragen, wenn sie eine im Klassenzimmer findet."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Notre grande sœur ne dit jamais rien de méchant. Elle est si gentille qu'elle a même remis l'araignée qui était rentrée dans la salle de classe dans la cour de l'école."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "HORIZON_ACT5_INTERLUDE1@45#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3500501
L45_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "CHILDREN_BARCODE_TWO_NULL"
L45_1.m_Pos = "R"
L45_1.m_Crash = 15
L46_1 = "아인은 거미 보고 울었어~"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "アインはクモを見てビビって泣いちゃったもんね～"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Eins cried when she saw the spider!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "艾茵看到蜘蛛還哭了喔～"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ไอนส์เห็นแมงมุมแล้วร้องไห้ด้วย!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Eins đã khóc khi nhìn thấy con nhện!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "艾因看到蜘蛛之后都哭了。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Eins hat geweint, als sie die Spinne gesehen hat!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Eins a pleuré quand elle a vu l'araignée !"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "HORIZON_ACT5_INTERLUDE1@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3500501
L46_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "UNIT_HATE"
L46_1.m_Face = L47_1
L46_1.m_CharStrID = "CHILDREN_BARCODE_ONE_NULL"
L46_1.m_Pos = "L"
L46_1.m_Crash = 10
L47_1 = "드, 드라이도 울었잖아! 네가 얼굴에 들이밀어서 그렇지!"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ド、ドライだって泣いてたもん！　目の前に突き出されてびっくりしただけだもん！"
L46_1.m_Talk_JPN = L47_1
L47_1 = "S-so did Drei! I only cried because you shoved it in my face!"
L46_1.m_Talk_ENG = L47_1
L47_1 = "特…特蘿伊還不是有哭！都嘛是因為你拿蜘蛛嚇我們！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ดะ-ไดรก็เหมือนกันแหละ! เค้าร้องเพราะตัวเอาใส่หน้าเค้าหรอก!"
L46_1.m_Talk_THA = L47_1
L47_1 = "Drei cũng vậy! Chị chỉ khóc vì em đã xô nó vào mặt chị!"
L46_1.m_Talk_VTN = L47_1
L47_1 = "德、德莱不也哭了吗！都怪你拿蜘蛛吓唬她！"
L46_1.m_Talk_SCN = L47_1
L47_1 = "D-Drei aber auch! Du hast sie mir vor die Nase gehalten!"
L46_1.m_Talk_DEU = L47_1
L47_1 = "D-Drei aussi a pleuré ! Et puis d'abord, c'est parce que tu me l'avais mise juste devant le visage !"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "HORIZON_ACT5_INTERLUDE1@47#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 47
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3500501
L47_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L47_1.m_bWaitClick = true
