L47_1.m_CharStrID = "CHILDREN_BARCODE_TWO_NULL"
L47_1.m_Pos = "R"
L47_1.m_Crash = 10
L48_1 = "울보래요~ 울보래요~ 아인은 울보래요~"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "泣き虫♪　泣き虫♪　アインは泣き虫♪"
L47_1.m_Talk_JPN = L48_1
L48_1 = "You're such a crybaby, Eins!"
L47_1.m_Talk_ENG = L48_1
L48_1 = "愛哭鬼～愛哭鬼～艾茵是愛哭鬼～"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ว้ายๆ ไอนส์ขี้แย!"
L47_1.m_Talk_THA = L48_1
L48_1 = "Chị đúng là một đứa trẻ hay khóc, Eins!"
L47_1.m_Talk_VTN = L48_1
L48_1 = "爱哭鬼~爱哭鬼~艾因是个爱哭鬼~"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Du bist so eine Heulsuse, Eins! Heulsuse, Heulsuse!"
L47_1.m_Talk_DEU = L48_1
L48_1 = "T'es qu'une pleurnicharde ! Eins, la pleureuse !"
L47_1.m_Talk_FRA = L48_1
