L4_1 = "얘, 얘들아. 배 위에서 뛰어다니면 할아버지한테 혼나."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "ちょ、ちょっと二人とも。船の上で走り回ったらおじいさんに怒られるよ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "N-now, now, girls… Grandpa will scold you if you run around on the ship."
L3_1.m_Talk_ENG = L4_1
L4_1 = "你們，不可以在船上奔跑，爺爺會生氣喔。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ดะ-เดี๋ยวเถอะเด็กๆ... วิ่งไปทั่วเรือแบบนี้คุณปู่จะดุเอานะ"
L3_1.m_Talk_THA = L4_1
L4_1 = "N-nào, nào, các em… Ông nội sẽ mắng đấy nếu cứ chạy lòng vòng trên tàu như thế."
L3_1.m_Talk_VTN = L4_1
L4_1 = "孩、孩子们。不可以在石头上乱跑，不然会被爷爷教训的。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "M-Mädels! Opa wird schimpfen, wenn ihr auf dem Schiff rennt."
L3_1.m_Talk_DEU = L4_1
L4_1 = "A-Allons, les filles... Grand-père va vous gronder si vous courez sur le bateau !"
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "HORIZON_ACT5_INTERLUDE1@54#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 54
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3500501
L4_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L4_1.m_Pos = "L"
L5_1 = "생체 정보 분석 결과, 저 아이들과 친족은 아니군요. 보호자 신분입니까."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "生体情報分析の結果、あの子たちと血の繋がりはないようですね。保護者ですか。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "My biometric analysis suggests that you are not their biological kin. Are you their legal guardian, perhaps?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "生物資訊分析結果。你和她們沒有親屬關係，你是她們的保護人嗎？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "การวิเคราะห์ชีวมาตรของฉันระบุว่าคุณไม่ใช่ญาติพี่น้องทางชีววิทยาของพวกเธอนี่คะ หรือคุณจะเป็นผู้ปกครอง?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Phân tích sinh trắc học của tôi cho thấy rằng cô không phải là họ hàng sinh học của họ. Có lẽ nào cô là người giám hộ hợp pháp của họ à?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "生物信息分析结果，你和那些孩子们不是亲戚。算是监护人吗？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Meine biometrische Analyse zeigt, dass Sie mit den Kindern nicht biologisch verwandt sind. Sind Sie ihre Erziehungsberechtigte?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Mon analyse biométrique m'indique que vous n'êtes pas liées par le sang. Êtes-vous leur tuteur légal ?"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "HORIZON_ACT5_INTERLUDE1@55#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 55
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3500501
L5_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_LAUGH"
L5_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L5_1.m_Pos = "R"
L6_1 = "아, 네. 일단은 저 아이들의 선생님으로 일하고 있는 중이에요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "あ、はい。一応あの子たちの先生として働かせてもらっています。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Oh, yes. I'm serving as their teacher for now."
L5_1.m_Talk_ENG = L6_1
L6_1 = "是的，我現在的工作是她們的老師。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "อ๋อ ใช่ค่ะ ตอนนี้ฉันทำหน้าที่เป็นครูพวกเธอค่ะ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Ồ, vâng. Tôi đang phục vụ với tư cách là giáo viên của họ bây giờ."
L5_1.m_Talk_VTN = L6_1
L6_1 = "啊，是的。我临时担任她们的老师工作。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Oh, sozusagen. Ich arbeite vorerst als ihre Lehrerin."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Oh, oui. À vrai dire, je suis leur enseignante."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "HORIZON_ACT5_INTERLUDE1@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3500501
L6_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_IDLE"
L6_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L6_1.m_Pos = "R"
L7_1 = "그러고 보니 제 소개가 늦었네요. 루시드라고 불러 주세요, 호라이즌 씨."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "そういえば自己紹介が遅れてしまいました。ルシードと呼んでください、ホライズンさん。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Oh, where are my manners. I forgot to introduce myself. Please call me Lucid, Ms. Horizon."
L6_1.m_Talk_ENG = L7_1
L7_1 = "這麼說來，我還沒自我介紹對吧？地平線小姐，我叫露西德。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "โอ๊ะ ฉันนี่เสียมารยาทจริงๆ เลยค่ะ ต้องแนะนำตัวก่อนสินะ ฉันชื่อลูซิดนะคะ คุณฮอไรซัน"
L6_1.m_Talk_THA = L7_1
L7_1 = "Ôi, phép tắc đâu cả rồi. Tôi quên giới thiệu bản thân. Vui lòng gọi tôi là Lucid, cô Horizon."
L6_1.m_Talk_VTN = L7_1
L7_1 = "这么说起来，我好像忘了自我介绍。请叫我露西德，地平线小姐。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ach ja, wie unhöflich von mir. Bitte nennen Sie mich Lucid, Miss Horizon."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Oh, mais où avais-je la tête. Je ne me suis même pas présentée. Vous pouvez m'appeler Lucid, mademoiselle Horizon."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "HORIZON_ACT5_INTERLUDE1@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3500501
L7_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "UNIT_HATE"
L7_1.m_Face = L8_1
L7_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L7_1.m_Pos = "L"
L8_1 = "……제 이름을 어디서 들었습니까, 휴먼?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "……私の名前はどこで聞いたのですか、ヒューマン？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "…Who told you my name, human?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "……人類，你從哪裡聽到我的名字的？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "... ไปรู้ชื่อฉันมาจากไหนคะมนุษย์?"
L7_1.m_Talk_THA = L8_1
L8_1 = "… Ai đã nói với cô tên tôi, con người?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "……你怎么会知道我的名字，人类？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Wer hat Ihnen meinen Namen gesagt, Mensch?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Qui vous a dit mon nom, humaine ?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
