L10_1 = "HORIZON_ACT5_INTERLUDE1@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3500501
L9_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "그렇게 경계하지 마시죠, 사채업자. 그 분들은 당신에 대해 알 자격이 있답니다."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "そんなに警戒しないでいただきたいですわ、闇金業者さん。その方たちはあなたについて知る資格があります。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "There's no need to get so defensive, loan shark girl. They have every right to know about you."
L9_1.m_Talk_ENG = L10_1
L10_1 = "放高利貸的，你不用那麼緊張。她們有資格知道關於你的事。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ไม่ต้องระแวงไปหรอกค่ะ สาวน้อยเจ้าหนี้หน้าเลือด พวกเขามีสิทธิ์ทุกประการจะรู้เรื่องเธอนะคะ"
L9_1.m_Talk_THA = L10_1
L10_1 = "Không cần phải cảnh giác như vậy, cô gái cho vay nặng lãi. Họ có mọi quyền để biết về cô."
L9_1.m_Talk_VTN = L10_1
L10_1 = "不需要这么警惕，高利贷小姐。他们有资格对你进行了解。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Werden Sie nicht so defensiv. Diese Leute haben jedes Recht, mehr über Sie zu erfahren."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Pas la peine d'être autant sur la défensive, Madame la préteuse sur gage. Elles ont tout à fait le droit de savoir qui tu es."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
