L13_1 = "HORIZON_ACT5_INTERLUDE1@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3500501
L12_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L12_1.m_Pos = "R"
L13_1 = "아, 죄송해요. 팬드래건 님. 티타임에 너무 소란스러웠죠."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "あっ、すみませんペンドラゴン様。ティータイムなのにうるさくしてしまって。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Oh, I apologize, Lady Pendragon. I didn't mean to intrude upon your teatime with all this ruckus."
L12_1.m_Talk_ENG = L13_1
L13_1 = "抱歉，潘德拉貢小姐，打擾你的下午茶時間。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "โอ๊ะ ขออภัยด้วยค่ะ ท่านหญิงเพ็นดราก้อน ฉันไม่ได้ตั้งใจจะรบกวนเวลาดื่มชาของคุณด้วยความอึกทึกพวกนี้เลยนะคะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Ồ, tôi xin lỗi, Cô Pendragon. Tôi không có ý định xâm phạm bầu không khí của cô với tất cả những điều náo nhiệt này."
L12_1.m_Talk_VTN = L13_1
L13_1 = "啊，对不起。伊丽莎白小姐。很抱歉打扰到了您的下午茶时间。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Oh, Entschuldigung, Lady Pendragon. Ich störe Ihre Teestunde mit meinem Lärm."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Oh, pardon, Mademoiselle Pendragon. Je ne voulais pas vous importuner pendant votre pause thé."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
