L15_1 = "HORIZON_ACT5_INTERLUDE1@64#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 64
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3500501
L14_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_PRIDE"
L15_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L15_1 = "사죄의 말은 아껴 두세요, 루시드 양."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "謝罪の言葉は必要ありませんわ、ルシードさん。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Save your apologies for when you really need them, Ms. Lucid."
L14_1.m_Talk_ENG = L15_1
L15_1 = "露西德小姐，不需要這麼客氣。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "เก็บคำขอโทษไว้ใช้เวลาที่จำเป็นจริงๆ เถอะค่ะคุณลูซิด"
L14_1.m_Talk_THA = L15_1
L15_1 = "Hãy để dành những lời xin lỗi khi cô thực sự cần, cô Lucid."
L14_1.m_Talk_VTN = L15_1
L15_1 = "不需要说对不起，露西德小姐。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Eine Entschuldigung ist nicht nötig, Fräulein Lucid."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Gardez vos excuses pour quand vous en aurez vraiment besoin, Lucid."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "HORIZON_ACT5_INTERLUDE1@65#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 65
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 3500501
L15_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L16_1 = "때로는 소란스러운 분위기 속에서 홍차의 여운을 즐기는 것도 제 낙이랍니다."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "時には騒がしい雰囲気の中で紅茶の味を堪能するのも一興ですもの。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Relishing in the subtle placidity of a cup of tea amidst such a ruckus as this is one of my small pleasures."
L15_1.m_Talk_ENG = L16_1
L16_1 = "有時候在熱鬧的氣氛中，品味紅茶的茶韻也是我的樂趣之一。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "การเพลิดเพลินกับความสงบเงียบอันละเอียดอ่อนของชาสักถ้วยท่ามกลางความอึกทึกแบบนี้\nก็เป็นความพอใจเล็กๆ นะคะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Thưởng thức sự nhẹ nhàng tinh tế của một tách trà giữa những ồn ào náo nhiệt như vậy là một trong những thú vui nhỏ của tôi."
L15_1.m_Talk_VTN = L16_1
L16_1 = "偶尔在喧闹的氛围中品味红茶的余韵，也是我的乐趣之一。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ich freue mich über eine entspannte Tasse Tee inmitten solcher Lebhaftigkeit."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Ça fait partie de mes petits plaisirs coupables que de savourer une tasse de thé dans un environnement tumultueux."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
