L19_1 = "HORIZON_ACT5_INTERLUDE1@68#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 68
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3500501
L18_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L18_1.m_Pos = "R"
L18_1.m_Crash = 10
L19_1 = "그, 그렇군요. 홍차의 세계는 정말 심오하네요……."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "そ、そうなんですね。紅茶の世界は実に奥深いものですね……"
L18_1.m_Talk_JPN = L19_1
L19_1 = "I-I see. I still have much to learn about the wonders of tea, I suppose…"
L18_1.m_Talk_ENG = L19_1
L19_1 = "原…原來如此，紅茶的世界真是深奧……"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ขะ-เข้าใจแล้วค่ะ ดูท่าว่าฉันยังต้องเรียนรู้เรื่องความอัศจรรย์ของชาอีกมาก..."
L18_1.m_Talk_THA = L19_1
L19_1 = "T-tôi thấy rồi. Tôi vẫn còn nhiều điều để tìm hiểu về những điều kỳ diệu của trà, tôi cho rằng…"
L18_1.m_Talk_VTN = L19_1
L19_1 = "是、是这样吗。红茶的世界果然很深奥……"
L18_1.m_Talk_SCN = L19_1
L19_1 = "A-ach so. Die Welt des Tees ist unergründlich, nehme ich an ..."
L18_1.m_Talk_DEU = L19_1
L19_1 = "J-Je vois. J'ai encore beaucoup à apprendre sur les merveilles du thé, je suppose..."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "HORIZON_ACT5_INTERLUDE1@69#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 69
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 3500501
L19_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L19_1.m_Pos = "L"
L20_1 = "이쪽은 어린이집 교사, 그쪽은 홍차 외판원이십니까?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "こちらは幼稚園の教員、そちらは紅茶のセールスマンですか？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "So she's a pre-school teacher. And you? Are you a tea peddler?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "這位是幼稚園老師，請問那位是賣紅茶的嗎？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ถ้าอย่างนั้นเธอก็เป็นครูปฐมวัยสินะคะ แล้วคุณล่ะคะ? คุณเป็นแม่ค้าใบชาเหรอคะ?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Cô ấy là một giáo viên mầm non sao. Còn cô? Cô có phải là người bán trà dạo không?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "她是幼儿园教师，那你是红茶品鉴师吗？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Okay, sie ist Vorschullehrerin, und Sie? Eine Teehändlerin?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Elle est donc enseignante dans une maternelle. Et vous ? Êtes-vous une marchande de thé ?"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
