L22_1 = "HORIZON_ACT5_INTERLUDE1@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3500501
L21_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_LAUGH"
L22_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "카운터 아카데미의 요청으로 크루즈 유람 체험 교육을 진행하게 된 엘리자베스 팬드래건이랍니다."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "カウンターアカデミーの要請を受け、クルーズ遊覧体験教育の進行役を勤めているエリザベス・ペンドラゴンと申します。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "I am Elizabeth Pendragon, currently chaperoning the educational cruise ship tour at the behest of the Counter Academy."
L21_1.m_Talk_ENG = L22_1
L22_1 = "我是受制裁者學院之邀，策畫郵輪體驗校外教學的伊莉莎白·潘德拉貢。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ฉันชื่อเอลิซาเบธ เพ็นดราก้อนค่ะ ขณะนี้เป็นผู้ควบคุมทัวร์ล่องเรือเพื่อการศึกษาตามคำขอร้องของสถาบันเคาน์เตอร์"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tôi là Elizabeth Pendragon, hiện đang phụ trách chuyến tham quan bằng tàu du lịch theo lệnh của Học Viện Counter."
L21_1.m_Talk_VTN = L22_1
L22_1 = "我是收到制裁者学院邀请，正在进行游轮体验教育的伊丽莎白·潘德拉贡。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ich bin Elizabeth Pendragon und ich leite auf Anfrage der Counter-Akademie eine Kreuzfahrt-Erlebnisführung."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Je suis Elizabeth Pendragon, je m'occupe de cette croisière éducationnelle à la demande de l'Académie des Counters."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "HORIZON_ACT5_INTERLUDE1@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3500501
L22_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "<color=#ffd34c>콜드 케이스</color>를 건지는 건 제가 제출했던 커리큘럼에 없었지만 말이죠."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "<color=#ffd34c>コールドケース</color>を引き揚げるのは私が提出したカリキュラムにはありませんでしたが。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Although I must admit, fishing a <color=#ffd34c>Cold Case</color> out of the water was not part of the curriculum I recommended."
L22_1.m_Talk_ENG = L23_1
L23_1 = "不過打撈<color=#ffd34c>Cold Case</color>的行程，並不在我提交的規劃裡。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "แต่ก็ต้องยอมรับนะคะว่า การตก<color=#ffd34c>โคลด์เคส</color>ขึ้นมาจากน้ำไม่ได้อยู่ในหลักสูตรที่ฉันแนะนำ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Mặc dù tôi phải thừa nhận, việc câu một <color=#ffd34c>Cold Case</color> lên khỏi mặt nước không phải là một phần của chương trình mà tôi đề xuất."
L22_1.m_Talk_VTN = L23_1
L23_1 = "但打捞<color=#ffd34c>诡异神器</color>并不在我的课程范围内。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Obwohl ich sagen muss, dass das Bergen eines <color=#ffd34c>Cold Case</color> nicht Teil des von mir eingereichten Lehrplans war."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Même si je dois avouer que repêcher une <color=#ffd34c>affaire classée</color> ne faisait pas partie de mon programme."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
