L27_1 = "HORIZON_ACT5_INTERLUDE1@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3500501
L26_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "RYAN_PRYDWEN_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "R_M_I"
L27_1 = "아가씨. 민감한 이야기는 자리를 옮겨서 하시죠."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "お嬢様、大事な話は場所を移してからなさるのはいかがでしょうか。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "My Lady. Perhaps we should discuss such sensitive subjects elsewhere."
L26_1.m_Talk_ENG = L27_1
L27_1 = "小姐，敏感的話題還是先換個地方再說吧。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ท่านหญิงครับ เรื่องละเอียดอ่อนเช่นนี้เราน่าไปคุยกันที่อื่นนะครับ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Quý cô của tôi. Có lẽ chúng ta nên thảo luận về những chủ đề nhạy cảm như vậy ở nơi khác."
L26_1.m_Talk_VTN = L27_1
L27_1 = "小姐。比较敏感的话题还是在别的场合再谈吧。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Fräulein, heikle Themen sollten wir woanders diskutieren."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Mademoiselle. Peut-être devrions-nous discuter de sujets sensibles dans un lieu plus approprié."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "HORIZON_ACT5_INTERLUDE1@77#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 77
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3500501
L27_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "L"
L28_1 = "그래야겠군요. 한창 성장 중인 아이들이 들어서 좋을 것 없을 테니까요."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "ええ。成長期の子どもたちが聞いて楽しい話ではないでしょう。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "You're quite right. Nothing good can come of innocent children stumbling upon such jabber."
L27_1.m_Talk_ENG = L28_1
L28_1 = "你說的沒錯，這些話不適合讓孩子們聽到。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ท่าจะจริงของคุณ ให้เด็กไร้เดียงสาต้องมาได้ยินเรื่องไร้สาระแบบนั้นก็ไม่มีอะไรดีขึ้นมา"
L27_1.m_Talk_THA = L28_1
L28_1 = "Cậu nói khá đúng. Không có gì tốt đẹp khi những đứa trẻ ngây thơ tình cờ gặp phải những trò đùa như vậy."
L27_1.m_Talk_VTN = L28_1
L28_1 = "那就先这样吧。让这些正在成长的孩子们听到了也不好。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Stimmt. Die Kinder sind noch zu jung, um mitzuhören."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Vous avez raison. Il vaut mieux éviter que des enfants innocents aient vent de cette discussion."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "HORIZON_ACT5_INTERLUDE1@78#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 78
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3500501
L28_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "L"
L29_1 = "이 배에는 다양한 시설이 있답니다. 그중에는 아주 조용한 장소도 있죠."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "この船には様々な施設がありますわ。その中にはとても静かな場所もあります。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "This ship is furnished with a wide variety of facilities. Including very quiet, private spaces."
L28_1.m_Talk_ENG = L29_1
L29_1 = "這艘船上有各式各樣的設施，當中也有非常安靜的空間。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "เรือลำนี้มีสิ่งอำนวยความสะดวกมากมายหลายอย่างนะคะ รวมทั้งพื้นที่ส่วนตัวที่เงียบมากด้วย"
L28_1.m_Talk_THA = L29_1
L29_1 = "Con tàu này được trang bị nhiều loại tiện nghi. Bao gồm những không gian rất yên tĩnh, riêng tư."
L28_1.m_Talk_VTN = L29_1
L29_1 = "这艘船上的设施功能非常齐全。其中也包括了一些非常安静，不容易被外人打扰的空间。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Dieses Schiff ist mit einer Vielzahl von Einrichtungen ausgestattet. Darunter gibt es auch sehr ruhige, private Räume."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Ce navire est doté d'une grande variété d'installations. Y compris d'espaces calmes où nous pourront discuter en toute tranquillité."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "HORIZON_ACT5_INTERLUDE1@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3500501
L29_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "L"
L30_1 = "어떤가요, 호라이즌 양?"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "いかがでしょう、ホライズンさん？"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Would you do us the honor, Ms. Horizon?"
L29_1.m_Talk_ENG = L30_1
L30_1 = "地平線小姐，你怎麼說呢？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "รบกวนให้เกียรติเราได้ไหมคะคุณฮอไรซัน?"
L29_1.m_Talk_THA = L30_1
L30_1 = "Cô có thể cho chúng tôi một vinh dự không, cô Horizon?"
L29_1.m_Talk_VTN = L30_1
L30_1 = "你怎么想，地平线小姐？"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Was meinen Sie dazu, Miss Horizon?"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Qu'en dis-tu, Horizon ?"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
