L31_1 = {}
L32_1 = "HORIZON_ACT5_INTERLUDE1@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3500501
L31_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "동의합니다. 행동 방침은 이야기를 들은 뒤에 결정하죠."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "同意します。行動方針は話を聞いてから決めます。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Agreed. I will defer determining my course of action until after this discussion."
L31_1.m_Talk_ENG = L32_1
L32_1 = "同意，下一步行動就等聽你說完再決定。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ตกลงค่ะ ฉันจะเลื่อนกำหนดการที่ต้องทำไปก่อนจนกว่าจะจบการสนทนานี้"
L31_1.m_Talk_THA = L32_1
L32_1 = "Đồng ý. Tôi sẽ trì hoãn việc xác định phương hướng hành động của mình cho đến sau cuộc thảo luận này."
L31_1.m_Talk_VTN = L32_1
L32_1 = "同意。可以听完你说的之后，再决定如何行动。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Das finde ich gut. Ich werde meine Handlungsvorgaben festlegen, nachdem ich mit Ihnen geredet habe."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Entendu. Je déciderai de mon plan d'action une fois cette discussion terminée."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
