L38_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "퓨처 앳 워 콜드 케이스 137번. 별칭 <color=#ffd34c>자동인형</color>."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "フューチャーアットウォーコールドケースNo.137。別称、<color=#ffd34c>自動人形</color>。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Future-at-War Cold Case No. 137. A.k.a. <color=#ffd34c>Automaton</color>."
L37_1.m_Talk_ENG = L38_1
L38_1 = "天啟兵器 Cold Case 137號。代號 <color=#ffd34c>自動機器人</color>。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "โคลด์เคสของฟิวเจอร์-แอท-วอร์หมายเลข 137 หรือเรียกว่า<color=#ffd34c>หุ่นยนต์</color>"
L37_1.m_Talk_THA = L38_1
L38_1 = "Cold Case Chiến Tranh Tương Lai số 137, hay còn gọi là <color=#ffd34c>Automaton</color>."
L37_1.m_Talk_VTN = L38_1
L38_1 = "天启兵器诡异神器137号。代号<color=#ffd34c>自动人偶</color>。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Future-at-War Cold Case Nr. 137. Auch bekannt als <color=#ffd34c>Automaton</color>."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Affaire classée No 137, Future-at-War. Nom de code <color=#ffd34c>Automate</color>."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "HORIZON_ACT5_INTERLUDE1@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3500501
L38_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "등신대 인형으로서, 내부는 생산년도와 생산지를 확인할 수 없는 기계부품으로 구성되어 있다……."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "等身大の人形で、内部は生産年度と生産地が確認できない機械部品で構成されている……"
L38_1.m_Talk_JPN = L39_1
L39_1 = "A life-size doll fitted with mechanical parts of unknown origin and year of production…"
L38_1.m_Talk_ENG = L39_1
L39_1 = "等身大小，內部是由無法確認製造日期和產地的機器零件所組成……"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ตุ๊กตาขนาดเท่าตัวจริงที่ติดตั้งชิ้นส่วนจักรกลไม่ทราบที่มาและปีที่ผลิต..."
L38_1.m_Talk_THA = L39_1
L39_1 = "Một con búp bê kích thước thật được trang bị các bộ phận cơ khí không rõ nguồn gốc và năm sản xuất…"
L38_1.m_Talk_VTN = L39_1
L39_1 = "作为等身人偶，内部由无法确认生产日期和生产地址的机械部件组成……"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Eine lebensgroße Puppe, ausgestattet mit mechanischen Teilen unbekannter Herkunft und unbekannten Baujahrs ..."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Une poupée grandeur nature, équipée de composants mécaniques dont l'origine et de date de production sont inconnues..."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "HORIZON_ACT5_INTERLUDE1@89#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 89
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3500501
L39_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "주목할 만한 기능을 확인할 수 없어 연구 보류."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "注目すべき機能が確認できないため、研究は保留。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "No notable features verified. Further research suspended."
L39_1.m_Talk_ENG = L40_1
L40_1 = "無法確認值得注意的功能，需再研究。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ไม่พบคุณสมบัติพิเศษอะไร ระงับการวิจัยเพิ่มเติมชั่วคราว"
L39_1.m_Talk_THA = L40_1
L40_1 = "Không có tính năng đáng chú ý nào được xác minh. Nghiên cứu tiếp theo bị đình chỉ."
L39_1.m_Talk_VTN = L40_1
L40_1 = "因无法确认是否有需要关注的功能，暂时停止研究。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Keine nennenswerten Merkmale konnten erkannt werden. Weitere Forschung steht aus."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Aucune fonction spécifique n'a été déterminée. Recherches suspendues."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "HORIZON_ACT5_INTERLUDE1@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3500501
L40_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L40_1.m_CharStrID = L41_1
L41_1 = "이상이 엠버 소장이 국제연합군에 제출했던 보고서랍니다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "以上がアンバー所長が国連軍に提出した報告書の内容です。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "That's what Director Ember wrote in her report to the Multinational Coalition Force."
L40_1.m_Talk_ENG = L41_1
L41_1 = "以上是琥珀所長提供給國際聯合軍隊的報告內容。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "นั่นคือสิ่งที่ผู้อำนวยการเอมเบอร์เขียนไว้ในรายงานที่ส่งให้กองกำลังผสมระหว่างประเทศนะคะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Đó là những gì Giám Đốc Ember đã viết trong báo cáo của cô ấy cho Lực Lượng Liên Minh Đa Quốc Gia."
L40_1.m_Talk_VTN = L41_1
L41_1 = "以上就是安珀所长提交给国际联合军的报告书。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Das schrieb Direktorin Ember in ihrem Bericht an die Multinationalen Vereinten Streitkräfte."
L40_1.m_Talk_DEU = L41_1
L41_1 = "C'est ce que la Directrice Ember a écrit dans son rapport destiné aux Forces de la Coalition Internationale."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "HORIZON_ACT5_INTERLUDE1@91#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3500501
L41_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "저라면 이런 소박한 이름 대신 <color=#ffd34c>유해</color> 정도로 붙였겠네요."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "私ならこんな素朴な名前の代わりに<color=#ffd34c>遺骸</color>と名付けたでしょう。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "If it was me, I'd have simply labeled this exhibit something along the lines of <color=#ffd34c>remains</color>."
L41_1.m_Talk_ENG = L42_1
L42_1 = "要是我的話，才不會取這麼低調的名字，應該要取像是<color=#ffd34c>遺骸</color>這種才對。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ถ้าเป็นฉัน คงแค่แปะป้ายว่าสิ่งนี้ไม่ต่างอะไรจาก<color=#ffd34c>ซากศพ</color>"
L41_1.m_Talk_THA = L42_1
L42_1 = "Nếu là tôi, tôi chỉ đơn giản gắn nhãn cho phần phụ mục này vài thông tin dọc theo dòng <color=#ffd34c>những gì còn lại</color>."
L41_1.m_Talk_VTN = L42_1
L42_1 = "如果是我来命名的话，可能会用<color=#ffd34c>遗骸</color>来替代现在的名字。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ich hätte das eher <color=#ffd34c>Überreste</color> oder ähnliches genannt, statt solch einen bescheidenen Namen zu wählen."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Si c'était moi, j'aurais tout simplement qualifié cela de <color=#ffd34c>vestiges</color>."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
