L45_1 = "HORIZON_ACT5_INTERLUDE1@94#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 94
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3500501
L44_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "체험 교육 진행자가 알아서는 안 될 내용을 알고 있군요. 퓨처 앳 워 관계자입니까."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "子どもの体験教育の担当者が\n知っていてはいけない内容を知っていますね。\nフューチャーアットウォーの関係者ですか。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "You know something that no school chaperone would be aware of. Are you affiliated with Future-at-War?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "校外教學的策畫人，怎麼會知道這麼多不該知道的事？你是天啟兵器的關係人嗎？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "คุณรู้เรื่องที่คนดูแลโรงเรียนไม่น่าจะรู้เรื่องด้วย คุณทำงานกับฟิวเจอร์-แอท-วอร์รึเปล่าคะ?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Cô biết điều gì đó mà không giám sát viên của trường nào có thể biết được. Cô có liên quan đến Chiến Tranh Tương Lai không?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "你知道很多作为体验教育者不该知道的内容。是天启兵器的相关人员吗？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Sie wissen Dinge, die keine Leiterin von Erlebnisführungen kennen sollte. Sind Sie mit Future-at-War affiliiert?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Vous avez des informations qu'une simple accompagnatrice d'école ne devrait pas avoir. Seriez-vous affiliée à Future-at-War ?"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "HORIZON_ACT5_INTERLUDE1@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3500501
L45_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_LAUGH"
L46_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "저희는 현실세계에 존재하는 아티팩트와 관련된 사안을 주의깊게 살피는 편이에요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "私たちは現実世界に存在するアーティファクト関連の事案を注意深く調査しています。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Let's just say we pay particularly close attention to information pertaining to artifacts that exist in the Normalside."
L45_1.m_Talk_ENG = L46_1
L46_1 = "我們一直都有在觀察人造神器在現世的情況。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "เอาเป็นว่าเราให้ความสนใจในข้อมูลเกี่ยวกับ\nอาร์ติแฟ็กต์ในนอร์มอลไซด์เป็นพิเศษแล้วกันค่ะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Tôi chỉ có thể nói là chúng tôi đặc biệt chú ý đến thông tin liên quan đến các thần khí tồn tại ở Normalside."
L45_1.m_Talk_VTN = L46_1
L46_1 = "我们比较关注现世存在的人造神器相关事件。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Wir achten nur genau auf alle Aspekte, die sich auf Artefakte beziehen, die in der Normalside existieren."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Dis-toi que nous prêtons une attention toute particulière aux informations en relation avec les artefacts qui existent dans le Vérimonde."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "HORIZON_ACT5_INTERLUDE1@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3500501
L46_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L47_1 = "퓨처 앳 워가 연구했던 콜드 케이스들도 예외는 아니랍니다."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "フューチャーアットウォーが研究していたコールドケースも例外ではありません。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "The Cold Cases studied by Future-at-War are no exception, of course."
L46_1.m_Talk_ENG = L47_1
L47_1 = "天啟兵器研究的Cold Case也不例外。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "แน่นอนว่าการศึกษาโคลด์เคสของฟิวเจอร์-แอท-วอร์ก็ไม่ใช่ข้อยกเว้นเช่นกัน"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tất nhiên, các Cold Case được nghiên cứu bởi Chiến Tranh Tương Lai cũng không phải là ngoại lệ."
L46_1.m_Talk_VTN = L47_1
L47_1 = "天启兵器曾经研究过的诡异神器也并不是例外。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Das schließt die Cold Cases mit ein, die von Future-at-War untersucht wurden."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Bien sûr, les affaires classées sur lesquelles Future-at-War s'est penché ne font pas exception."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "HORIZON_ACT5_INTERLUDE1@97#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 97
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3500501
L47_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_IDLE"
L48_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "당시 개입하지 않았던 이유는 간단합니다. 관리국의 중재 때문이었죠."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "当時介入しなかった理由は簡単です。管理局の仲裁のせいでした。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "There's only one reason why we did not intervene back then. It was due to the arbitration of the Administration."
L47_1.m_Talk_ENG = L48_1
L48_1 = "而當時未介入的原因很簡單，因為管理局的仲裁。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เหตุผลเดียวที่ตอนนั้นเราไม่เข้าไปก้าวก่ายก็คือ มันเป็นไปตามการชี้ขาดขององค์การบริหารโลกค่ะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Chỉ có một lý do tại sao chúng tôi không can thiệp vào thời điểm đó. Đó là do sự phân xử của Cục Quản Lý."
L47_1.m_Talk_VTN = L48_1
L48_1 = "当时没有介入的原因也很简单。是因为有管理局的仲裁。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Es gibt einen einfachen Grund dafür, warum wir damals nicht eingegriffen haben – nämlich die Schlichtung durch die Administration."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Si nous n'avons rien fait à l'époque, c'est uniquement à cause de l'intervention de l'Administration."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "HORIZON_ACT5_INTERLUDE1@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3500501
L48_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "우려대로, 많은 아티팩트가 퓨처 앳 워 계획이 공중분해 되면서 사라졌지만 말이에요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "そして懸念どおり、多くのアーティファクトが\nフューチャーアットウォー計画の空中分解によって消えてしまいました。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Just as we feared, though, too many artifacts vanished into thin air when the Future-at-War plan fell through."
L48_1.m_Talk_ENG = L49_1
L49_1 = "雖然果真如我們所料，許多人造神器在天啟兵器計畫解散後消失不見。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "แต่ถึงอย่างนั้น เรื่องก็เป็นไปตามที่เรากลัว คือพอแผนของฟิวเจอร์-แอท-วอร์ไม่เป็นดังคาด ก็มีอาร์ติแฟ็กต์หายไปอย่างไร้ร่องรอยมากชิ้นเกินไป"
L48_1.m_Talk_THA = L49_1
L49_1 = "Tuy nhiên, đúng như chúng tôi lo sợ, quá nhiều thần khí đã biến mất không dấu vết khi kế hoạch của Chiến Tranh Tương Lai bị thất bại."
L48_1.m_Talk_VTN = L49_1
L49_1 = "就像我们担心的那样，有很多人造神器在天启兵器计划破产时消失了。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Doch wie wir befürchtet haben, haben sich viele Artefakte in Luft aufgelöst, als der Plan von Future-at-War-Plan gescheitert ist."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Mais comme nous le craignions, de nombreux artefacts se sont volatilisés lorsque le projet Future-at-War ont fini par échouer."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "HORIZON_ACT5_INTERLUDE1@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3500501
L49_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "UNIT_HATE"
L49_1.m_Face = L50_1
L49_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L49_1.m_Pos = "C"
L50_1 = "그래서 저를 제압하고 프레임을 확보할 계획입니까, 휴먼?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "それで、私を制圧してフレームを確保する計画ですか、ヒューマン？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Do you then plan to overpower me and take custody of the frame, human?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "所以你是想抓住我後拿走這副軀殼嗎，人類？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "นี่คุณตั้งใจจะใช้กำลังที่มากกว่ามาควบคุมตัวฉันไว้เหรอคะมนุษย์?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Vậy cô có định chế ngự tôi và giành quyền kiểm soát bộ khung không, con người?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "所以，你们要制伏我，然后拿走我的躯壳吗，人类？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Haben Sie nun vor, mich zu überwältigen und den Rahmen in Gewahrsam zu nehmen, Mensch?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Et donc vous comptez me maîtriser par la force et prendre possession de mon armature, c'est bien cela, humaine ?"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
