L3_1 = "HORIZON_ACT5_INTERLUDE1@102#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 102
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 3500501
L2_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_LAUGH"
L3_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "R"
L3_1 = "그럴 계획은 없어요, 호라이즌 양. 당분간은 말이죠."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "そういう計画はありませんわ、ホライズンさん。当分の間は、ですが。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "I have no such plans, Ms. Horizon. At least not yet."
L2_1.m_Talk_ENG = L3_1
L3_1 = "我沒這個意思……暫時……"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ฉันไม่มีความตั้งใจเช่นนั้นค่ะคุณฮอไรซัน อย่างน้อยก็ตอนนี้"
L2_1.m_Talk_THA = L3_1
L3_1 = "Tôi không có kế hoạch như vậy, cô Horizon. Ít nhất là chưa."
L2_1.m_Talk_VTN = L3_1
L3_1 = "我们没有那种计划，地平线小姐。暂时来说。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Es gibt keine derartigen Pläne, Miss Horizon. Zumindest vorerst."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Cela ne fait pas partie de mes plans, Horizon. Du moins, pas pour l'instant."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "HORIZON_ACT5_INTERLUDE1@103#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3500501
L3_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L3_1.m_Pos = "L"
L4_1 = "그렇다면 어째서 이 바다 한복판에서 커뮤니케이션을 해야 하는지 의문이군요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "では、なぜ私たちがこの海のど真ん中でコミュニケーションをしているのか疑問ですね。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Then I do not see why we must hold this discourse in the middle of the ocean."
L3_1.m_Talk_ENG = L4_1
L4_1 = "那我們為何要在這大海中央談話呢？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ถ้าอย่างนั้นฉันก็ไม่เห็นความจำเป็นที่เราต้องคุยเรื่องนี้กันต่อกลางมหาสมุทรนะคะ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Vậy thì tôi không hiểu tại sao chúng ta phải tổ chức bài diễn văn này ở giữa đại dương."
L3_1.m_Talk_VTN = L4_1
L4_1 = "如果是这样，那我们为什么要在海上进行这次沟通呢。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Dann verstehe ich nicht, warum wir mitten auf dem Ozean kommunizieren."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Dans ce cas, je ne vois pas pourquoi nous avons cette conversation au beau milieu de l'océan."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "HORIZON_ACT5_INTERLUDE1@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3500501
L4_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "R"
L5_1 = "제가 당신을 만나러 온 까닭은, 당신이 제프티 바이오테크와 대립하기 때문이에요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "私があなたに会いに来た理由は、あなたがジェフティ・バイオテックと対立しているためです。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "I came to see you because you are currently at odds with Jehuty Biotech."
L4_1.m_Talk_ENG = L5_1
L5_1 = "我之所以會來找你，正是因為你和傑夫堤生物科技是對立的。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ที่ฉันมาพบคุณก็เพราะตอนนี้คุณกำลังมีปัญหาขัดแย้งกับเจฮูตีไบโอเทคค่ะ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Tôi đến gặp cô vì cô hiện đang có xung đột với Jehuty Biotech."
L4_1.m_Talk_VTN = L5_1
L5_1 = "我来见你是因为，你和杰普提生物科技是对立关系。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Ich wollte sie sprechen, weil Sie derzeit gegen Jehuty Biotech vorgehen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Si je suis venue jusqu'ici pour te rencontrer, c'est parce que tu t'es mise à dos Jehuty Biotech."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "HORIZON_ACT5_INTERLUDE1@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3500501
L5_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_DESPAIR"
L6_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "R"
L6_1 = "표면적으로는 합법적인 기업 같지만, 내부가 어떤지는……."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "表面上は合法的な企業に見えますが、内部がどうなのかは……"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Although they may appear to be a legitimate business on the outside…"
L5_1.m_Talk_ENG = L6_1
L6_1 = "那間公司外表看似正派經營，但裡面呢……"
L5_1.m_Talk_TWN = L6_1
L6_1 = "แม้ภายนอกแล้วพวกเขาดูจะเป็นธุรกิจที่ถูกต้องตามกฎหมาย..."
L5_1.m_Talk_THA = L6_1
L6_1 = "Mặc dù bề ngoài họ có thể là một doanh nghiệp hợp pháp…"
L5_1.m_Talk_VTN = L6_1
L6_1 = "虽然他们表面看起来合法，但内部……"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Sie sehen nach außen hin aus wie ein seriöses Unternehmen, doch intern ..."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Bien qu'ils aient l'air tout à fait légitimes d'un point de vue externe..."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "HORIZON_ACT5_INTERLUDE1@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3500501
L6_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_IDLE"
L7_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "R"
L7_1 = "당신도 이미 직접 확인해 보셨겠죠."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "あなたもすでに、ご自身の目で確かめたのでしょう。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "I'm sure you saw for yourself their true nature."
L6_1.m_Talk_ENG = L7_1
L7_1 = "你應該也親自確認過吧？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "แต่ฉันแน่ใจค่ะว่าคุณเห็นธาตุแท้ของพวกเขามากับตาแล้ว"
L6_1.m_Talk_THA = L7_1
L7_1 = "Tôi chắc rằng cô đã tự mình nhìn thấy bản chất thực sự của họ."
L6_1.m_Talk_VTN = L7_1
L7_1 = "你应该已经亲眼确认过了。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ich bin sicher, dass Sie sich bereits selbst überzeugen konnten."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Je suis sûre que tu as déjà eu un avant goût de leur véritable nature."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "HORIZON_ACT5_INTERLUDE1@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3500501
L7_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L7_1.m_Pos = "L"
L8_1 = "당신은 유능한 카운터로 추정됩니다만. 본인이 나설 계획은 없는 겁니까."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "あなたは有能なカウンターと推定されますが、自身で直接解決する計画はないのですか。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "You strike me as a capable Counter. Why not strike them yourself?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "我看你應該也是位出色的制裁者，你不打算親自出馬嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "คุณจู่โจมฉันอย่างเคาน์เตอร์เก่งๆ ทำไมไม่จู่โจมพวกเขาเองล่ะคะ?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Cô làm tôi ấn tượng rằng cô là một Counter có khả năng. Tại sao không tự mình tấn công họ đi?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "我推测你也是一位有能力的制裁者。你没有计划要亲自出手吗？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Sie scheinen mir ein fähiger Counter zu sein. Warum greifen Sie nicht selbst ein?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Vous semblez être une Counter des plus compétentes, alors pourquoi ne pas passer à l'offensive par vous-même ?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "HORIZON_ACT5_INTERLUDE1@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3500501
L8_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_PRIDE"
L9_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "R"
L9_1 = "제프티 바이오테크는 저희와 오랜 시간 마찰을 빚어 온 세력의 하부 조직이랍니다."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "ジェフティ・バイオテックは私たちと長い間軋轢を生んできた勢力の下部組織です。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Jehuty Biotech is a subordinate organization of a faction with which we have a long history of conflict."
L8_1.m_Talk_ENG = L9_1
L9_1 = "傑夫堤生物科技，依附在與我們長期處不合的勢力底下。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เจฮูตีไบโอเทคเป็นแค่องค์กรลูกของฝ่ายหนึ่งที่ขัดแย้งกับเรามาช้านานค่ะ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Jehuty Biotech là một tổ chức trực thuộc của một phe mà chúng tôi có lịch sử xung đột lâu đời."
L8_1.m_Talk_VTN = L9_1
L9_1 = "杰普提生物科技是与我们有过长时间摩擦的某个势力的下属组织。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Jehuty Biotech ist die untergeordnete Organisation einer Fraktion, mit der wir seit langem in Konflikt stehen."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Jehuty Biotech est une organisation subalterne d'une faction avec laquelle nous avons longtemps été en conflit."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "HORIZON_ACT5_INTERLUDE1@109#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3500501
L9_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "R"
L10_1 = "안타깝지만, 혼란이 수습된 현재 그들과 전면전을 일으키는 건 부담이 크죠."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "残念ですが、混乱が収まった現在、彼らと全面戦争を起こすのは負担が大きいのです。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Regrettably, waging an all-out war with them so immediately after the return of stability would bear many risks."
L9_1.m_Talk_ENG = L10_1
L10_1 = "可惜的是，混亂結束後，現在要和他們正面交鋒的話負擔太大。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "น่าเสียใจนะคะ การทำสงครามสุดตัวกับพวกเขาทันทีที่ความมั่นคงกลับคืนมาจะทำให้\nต้องเผชิญความเสี่ยงหลายประการ"
L9_1.m_Talk_THA = L10_1
L10_1 = "Đáng tiếc, tiến hành một cuộc chiến toàn lực với họ ngay sau khi ổn định trở lại sẽ chịu nhiều rủi ro."
L9_1.m_Talk_VTN = L10_1
L10_1 = "很遗憾，在刚结束混乱的现在就开启与他们的全面战争，对我们来说也有很大负担。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Leider kommt derzeit im Angesicht der neugewonnen Stabilität ein umfassender Krieg mit ihnen nicht in Frage."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Malheureusement, entrer en guerre ouverte avec eux risquerait de compromettre cette stabilité tout juste retrouvée."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
