L12_1 = "HORIZON_ACT5_INTERLUDE1@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3500501
L11_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "그래서 <color=#ffd34c>오래된 목소리</color>의 조언대로 당신을 만나러 온 거예요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "ですので、<color=#ffd34c>古き声</color>の助言どおりあなたに会いに来たのです。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "That's why we came to see you, per the advice of the <color=#ffd34c>Old Voice</color>."
L11_1.m_Talk_ENG = L12_1
L12_1 = "所以才會照著<color=#ffd34c>老聲音</color>的建議來找你。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "และเพราะแบบนั้นฉันเลยมาพบคุณตามคำแนะนำของ<color=#ffd34c>เสียงอดีต</color>ค่ะ"
L11_1.m_Talk_THA = L12_1
L12_1 = "Đó là lý do tại sao chúng tôi đến gặp cô, theo lời khuyên của <color=#ffd34c>Old Voice</color>."
L11_1.m_Talk_VTN = L12_1
L12_1 = "所以，我按照<color=#ffd34c>老朋友</color>的建议来见你。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Deshalb haben wir den Rat der <color=#ffd34c>Alten Stimme</color> befolgt und sind hier, um Sie zu treffen."
L11_1.m_Talk_DEU = L12_1
L12_1 = "C'est pour ça que je suis venue te rencontrer, selon les conseils de l'<color=#ffd34c>ancienne voix</color>."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "HORIZON_ACT5_INTERLUDE1@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3500501
L12_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L12_1.m_Pos = "C"
L13_1 = "휴먼들의 복잡한 갈등 관계를 이해하기 위해 시간을 소모하는 것은 거부하겠습니다."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "ヒューマンたちの複雑な対立関係を理解するために時間を消耗することは拒否します。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "I refuse to waste any time trying to understand such a complicated conflict between humans."
L12_1.m_Talk_ENG = L13_1
L13_1 = "我拒絕花時間理解人類間複雜的利弊關係。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ฉันขอปฏิเสธไม่เสียเวลาไปกับการทำความเข้าใจความขัดแย้งอันซับซ้อนของมนุษย์นะคะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Tôi từ chối lãng phí bất kỳ thời gian nào để cố gắng hiểu một cuộc xung đột phức tạp như vậy giữa con người."
L12_1.m_Talk_VTN = L13_1
L13_1 = "我拒绝为了理解人类之间的复杂纠葛关系浪费时间。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ich weigere mich, Zeit zu verschwenden, um komplizierte Konflikte der Menschen zu verstehen."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Je refuse de perdre davantage de temps à essayer de comprendre un conflit entre humains aussi compliqué."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "HORIZON_ACT5_INTERLUDE1@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3500501
L13_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L13_1.m_Pos = "C"
L14_1 = "저는 채무자와 정산만 마치면 됩니다. 당신들의 용병 노릇을 할 생각은 없습니다."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "私は債務者と精算さえ済ませればそれでいいです。あなたたちの傭兵になるつもりはありません。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "All I need to do is settle the account with my debtor. I have no desire to serve as your mercenary."
L13_1.m_Talk_ENG = L14_1
L14_1 = "我只想處理和債務人之間的債務，不打算成為你們的傭兵。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ที่ฉันต้องทำมีเพียงแค่การปิดบัญชีกับลูกหนี้ค่ะ ฉันไม่มีความปรารถนาจะทำหน้าที่เป็นทหารรับจ้างของคุณ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Tất cả những gì tôi cần làm là tất toán khoản tiền với con nợ của tôi. Tôi không có mong muốn phục vụ như một lính đánh thuê của cô."
L13_1.m_Talk_VTN = L14_1
L14_1 = "我只要和债务者完成结算就可以了。不想成为你们的佣兵。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ich will lediglich die Rechnungen meiner Schuldner begleichen. Ich denke nicht daran, als Ihr Söldner zu dienen."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Mon unique objectif est simple : régler mes comptes avec mon débiteur. Je n'ai nullement l'intention de vous servir de mercenaire."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
