L17_1 = "HORIZON_ACT5_INTERLUDE1@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3500501
L16_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "R"
L17_1 = "제 제안과 관계없이 저들을 무너뜨리겠다는 뜻으로 들리는군요."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "私の提案と関係なく、彼らを倒すという意味に聞こえますわね。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "That sounds like you'll bring them down regardless of my proposition."
L16_1.m_Talk_ENG = L17_1
L17_1 = "我的意思不是要你除掉他們。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ฟังดูเหมือนคุณปัดข้อเสนอทิ้งโดยไม่สนใจว่าฉันอยู่ในฐานะอะไรเลยนะคะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Nghe có vẻ như cô sẽ hạ gục chúng bất kể tôi có đề xuất gì."
L16_1.m_Talk_VTN = L17_1
L17_1 = "听起来就算没有我的提议，你也想打倒他们。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Das klingt, als würden Sie sie auch ohne meinen Vorschlag zu Fall bringen wollen."
L16_1.m_Talk_DEU = L17_1
L17_1 = "On dirait bien que tu vas t'occuper d'eux, peu importe ma proposition."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
