L19_1 = "HORIZON_ACT5_INTERLUDE1@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3500501
L18_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "R"
L19_1 = "딘 코너, 본명 윌버 웨이틀리 대표는 17시간 전 샤레이드 소재의 본사에 도착했어요."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "ディーン・コナー、本名ウィルバー・ウェイトリー代表は17時間前、シャレードの本社に到着しました。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Dean Conner, real name Wilbur Whateley, arrived at his corporate HQ in Charade as of 17 hours ago."
L18_1.m_Talk_ENG = L19_1
L19_1 = "狄恩•康納，也就是韋爾伯·韋特利代表，在17小時前曾經造訪過位在查雷德的總公司。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ดีน คอนเนอร์ ชื่อจริงวิลเบอร์ เวตลีย์ มาถึงศูนย์บัญชาการของเขาเมื่อ 17 ชั่วโมงก่อน"
L18_1.m_Talk_THA = L19_1
L19_1 = "Dean Conner, tên thật là Wilbur Whateley, đã đến trụ sở công ty của mình ở Charade vào 17 giờ trước."
L18_1.m_Talk_VTN = L19_1
L19_1 = "迪姆·科纳，本名为韦尔伯·维特利，在17个小时前抵达查雷德所在的总公司。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Dean Conner, mit bürgerlichem Namen Wilbur Whateley, ist vor 17 Stunden in seinem Hauptquartier in Charade eingetroffen."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Dean Conner, ou plutôt devrais-je dire Wilbur Whateley, est arrivé au Quartier général de son entreprise il y a environs 17 heures."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "HORIZON_ACT5_INTERLUDE1@119#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 3500501
L19_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "R"
L20_1 = "아마 그곳에서 관리국의 보호를 받으며 농성할 생각이겠죠."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "おそらくそこで管理局の保護を受けながら立てこもるつもりでしょう。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "He will likely endure the siege there under the protection of the Administration."
L19_1.m_Talk_ENG = L20_1
L20_1 = "他可能是想取得管理局的保護後借題發揮。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "เขาอาจจะตั้งรับการล้อมปราบที่นั่นภายใต้การคุ้มครองขององค์การบริหารโลก"
L19_1.m_Talk_THA = L20_1
L20_1 = "Anh ta có thể sẽ phải chịu đựng cuộc bao vây ở đó dưới sự bảo vệ của Cục Quản Lý."
L19_1.m_Talk_VTN = L20_1
L20_1 = "他们可能是想在接受管理局保护的前提下，在那里进行固守。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Wahrscheinlich hat er vor, die Belagerung unter dem Schutz der Administration zu überstehen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Je suis persuadée qu'il n'aura aucune difficulté à y tenir un siège sous la protection de l'Administration."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "HORIZON_ACT5_INTERLUDE1@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 3500501
L20_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L20_1.m_Pos = "L"
L21_1 = "건축물의 방호력 때문입니까?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "建築物の防護力を信じているからですか？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Do the structures there provide him reliably protective shelter?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "是因為建築物的防護力嗎？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "อาคารที่นั่นเป็นที่หลับภัยที่เขาวางใจได้เหรอคะ?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Các cấu trúc ở đó có đảm bảo cho anh ta nơi trú ẩn đáng tin cậy không?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "是妄想凭借建筑物的防御力吗？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Erhofft er sich etwa Abschirmung durch die Bauten?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Voulez-vous dire que le bâtiment lui offre une protection efficace ?"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
