L24_1 = "HORIZON_ACT5_INTERLUDE1@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3500501
L23_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L23_1.m_CharStrID = L24_1
L24_1 = "틀렸어요. 당신들과 이면세계를 탐사할 때 얻은 아티팩트 때문이랍니다."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "いいえ。あなたたちと裏世界を探査した際に手に入れたアーティファクトがあるからです。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "That's not it. He's counting on the artifact he acquired during his expedition to the Counterside with you."
L23_1.m_Talk_ENG = L24_1
L24_1 = "不是，是與你們勘查異界時取得的人造神器有關。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ไม่ใช่แบบนั้นค่ะ เขาหวังพึ่งอาร์ติแฟ็กต์ที่ได้มาตอนเดินทางไปเคาน์เตอร์ไซด์กับคุณ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Không phải vậy đâu. Anh ta đang trông cậy vào thần khí mà anh ta có được trong chuyến thám hiểm tới Counterside cùng cô."
L23_1.m_Talk_VTN = L24_1
L24_1 = "你错了。是凭借进行异界探索时获得的人造神器。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Falsch. Er zählt auf das Artefakt, das er während seiner Expedition mit Ihnen in der Counterside erhalten hat."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Non. Il compte sur l'artefact qu'il a récupéré lors de son expédition dans le Contremonde avec vous autres."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "HORIZON_ACT5_INTERLUDE1@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3500501
L24_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L25_1 = "데몬 타입 침식체를 불러냈던 그 이상한 카메라 말이군요. 기록에 남아 있습니다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "デーモンタイプ侵食体を呼び出したあの不思議なカメラのことですね。記録に残っています。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "You must mean that strange camera that summoned a Demon-Type C.O. There remains a record of it in my log files."
L24_1.m_Talk_ENG = L25_1
L25_1 = "原來是指那個曾經召喚出惡魔型侵蝕體的奇怪相機。我還留有紀錄。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "คุณคงหมายถึงกล้องแปลกๆ ที่เรียกC.O. ประเภทดีม่อนออกมาได้ เรื่องนั้นยังอยู่ในไฟล์บันทึกของฉันค่ะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Ý của cô là chiếc máy ảnh kỳ lạ đã triệu hồi V.T.A.M. Loại Quỷ Dữ. Vẫn còn một bản ghi về nó trong các tệp nhật ký của tôi."
L24_1.m_Talk_VTN = L25_1
L25_1 = "是说曾经召唤出恶魔型侵蚀体的那个奇怪相机吧。我还留有记录。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Sie meinen wohl diese seltsame Kamera, die einen C.°O. des Dämonen-Typus beschworen hat. Eine Aufzeichnung davon ist in meinem Verlauf."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Vous devez parler de cet étrange appareil photo qui avait invoqué un Objet Corrompu de type démon. Il reste encore des archives de cet incident dans mes historiques."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "HORIZON_ACT5_INTERLUDE1@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3500501
L25_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "네. 멸망한 세계의 <color=#ffd34c>특정 피사체</color>들을 일시적으로 모방하는 아티팩트…… 라고 저희는 추정하고 있죠."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "はい。滅亡した世界の<color=#ffd34c>特定被写体</color>を一時的にコピーするアーティファクト……と私たちは推測していますわ。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "That's right. It's an artifact that temporarily imitates <color=#ffd34c>specific objects</color> from extinct worlds… Well, that's our hypothesis anyway."
L25_1.m_Talk_ENG = L26_1
L26_1 = "沒錯，我們推測那應該是，可以暫時模仿滅亡世界的<color=#ffd34c>特定拍攝對象</color>的人造神器……"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ใช่แล้วค่ะ มันคืออาร์ติแฟ็กต์ที่จะลอกเลียนแบบ<color=#ffd34c>วัตถุเฉพาะชิ้น</color>จากโลกที่ดับสูญไปแล้วได้ชั่วคราว... แต่นั่นก็เป็นสมมติฐานของเรานะคะ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Đúng rồi. Đó là một thần khí tạm thời bắt chước <color=#ffd34c>các vật thể cụ thể</color> từ các thế giới đã tuyệt chủng… Chà, đó là giả thuyết của chúng tôi."
L25_1.m_Talk_VTN = L26_1
L26_1 = "是的。我们推测……那是可以短暂模仿已灭亡世界的<color=#ffd34c>特定被拍摄物</color>的人造神器。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Genau. Es ist ein Artefakt, das vorübergehend <color=#ffd34c>bestimmte Objekte</color> aus untergegangenen Welten imitiert ... Zumindest ist das unsere Hypothese."
L25_1.m_Talk_DEU = L26_1
L26_1 = "C'est exact. Il s'agit d'un artefact qui peut imiter temporairement des <color=#ffd34c>objets spécifiques</color> de mondes disparus."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "HORIZON_ACT5_INTERLUDE1@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3500501
L26_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L26_1.m_CharStrID = L27_1
L27_1 = "가급적 저희가 확보할 수 있길 바라고 있어요. 세상에 돌아다니게 두기에는 위험한 물건이니까요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "できれば私たちで確保しておきたいと考えています。放っておくには危険な物ですから。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "We're hoping to secure it if at all possible. It's far too dangerous to leave it out there in the world."
L26_1.m_Talk_ENG = L27_1
L27_1 = "可以的話，希望是由我們來保管，畢竟讓那個東西留在世界上是很危險的。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ถ้าเป็นไปได้เราก็หวังว่าจะยึดมันมาได้ การปล่อยมันไว้ในโลกนี้เป็นเรื่องอันตรายเกินไปค่ะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Chúng tôi hy vọng sẽ bảo mật nó nếu có thể. Quá nguy hiểm nếu để nó lưu lạc ngoài thế giới."
L26_1.m_Talk_VTN = L27_1
L27_1 = "我希望尽量由我们来保管。放任那个物品流落在世界上太危险了。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Wir hoffen, es sichern zu können. Es ist viel zu gefährlich, als dass es in der Welt kursieren dürfte."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Nous espérons en prendre possession, si toutefois cela est possible. Cet artefact est bien trop dangereux pour que nous le laissions au dehors, à la portée de n'importe qui."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
