L30_1 = "HORIZON_ACT5_INTERLUDE1@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3500501
L29_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_DESPAIR"
L29_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L29_1.m_Pos = "C"
L30_1 = "당신들은 믿어도 된다는 말처럼 들리는군요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "私たちを信じてほしい、と言っているように聞こえますが。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "You speak as though you are trying to convince me of your trustworthiness."
L29_1.m_Talk_ENG = L30_1
L30_1 = "聽起來似乎可信度滿高的。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "คุณพูดเหมือนกำลังพยายามให้ฉันเชื่อว่าคุณไว้ใจได้เลยนะคะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Cô nói như thể cô đang cố gắng thuyết phục tôi về sự đáng tin cậy của cô."
L29_1.m_Talk_VTN = L30_1
L30_1 = "怎么听起来好像是在说我可以信任你。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Sie wollen mich anscheinend von Ihrer Vertrauenswürdigkeit überzeugen."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Vous me parlez comme si vous essayiez de me convaincre que vous êtes digne de confiance."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "HORIZON_ACT5_INTERLUDE1@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3500501
L30_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_PRIDE"
L31_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "염려 마세요. 신사도 숙녀도, 언변으로 믿음을 얻으려 하지 않는답니다."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ご心配なく。紳士も淑女も、口弁で信頼を得ようとはしませんわ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Don't worry. A gentleman does not try to win over hearts with words alone… And neither does a lady."
L30_1.m_Talk_ENG = L31_1
L31_1 = "你放心，紳士或淑女，是不會只出一張嘴就想博得信任的。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ไม่ต้องห่วงค่ะ สุภาพบุรุษไม่เอาพยายามชนะใจใครด้วยแค่คำพูด... สุภาพสตรีก็เช่นกัน"
L30_1.m_Talk_THA = L31_1
L31_1 = "Đừng lo lắng. Một quý ông không cố gắng thu phục trái tim chỉ bằng lời nói… Và quý cô cũng vậy."
L30_1.m_Talk_VTN = L31_1
L31_1 = "别有太多顾虑。不管是绅士还是淑女，绝不会单凭语言就想取得对方信任。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Keine Sorgen. Weder ein Gentleman noch eine Lady versucht, nur mit Worten zu überzeugen."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Pas d'inquiétude. Un gentilhomme ne cherche jamais à conquérir les cœurs uniquement avec ses belles paroles, et il en va de même pour moi."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "HORIZON_ACT5_INTERLUDE1@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3500501
L31_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "FX_CUTSCEN_NOISE_RUSTLE_03"
L31_1.m_StartFXSoundName = L32_1
L32_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "행동으로 증명할 따름이죠."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "行動で証明するのみです。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "We simply prove ourselves through action."
L31_1.m_Talk_ENG = L32_1
L32_1 = "我們會以行動證明。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เราพิสูจน์ตัวเองผ่านการกระทำค่ะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Chúng tôi chỉ đơn giản là chứng minh bản thân thông qua hành động."
L31_1.m_Talk_VTN = L32_1
L32_1 = "只会用行动来证明。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Nein, Taten müssen folgen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Nos actions valent plus que nos mots."
L31_1.m_Talk_FRA = L32_1
