L36_1 = "버, 벌써 떠나시려는 건가요?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "も、もう帰られるのですか？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "L-leaving so soon?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "你…你要走了嗎？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "จะ-จะไปแล้วเหรอคะ?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Đ-đi sớm vậy?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "这、这么快就要离开吗？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "W-wollen Sie schon gehen?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "V-Vous partez déjà ?"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "HORIZON_ACT5_INTERLUDE1@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3500501
L36_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_IDLE"
L36_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L36_1.m_Pos = "C"
L37_1 = "그렇습니다만. 대출 상담을 원하십니까, 휴먼."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "そうです。貸付けの相談をご希望ですか、ヒューマン。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Yes. Did you wish to make a loan inquiry, human?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "沒錯，還是你有資金需求嗎，人類？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ค่ะ อยากทำเรื่องกูยืมเงินมั้ยคะมนุษย์?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Ừ. Cô muốn tư vấn khoản vay à, con người?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "是的。你想要贷款吗，人类。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ja. Wünschen Sie eine Darlehensberatung, Mensch?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Oui. Souhaitez-vous faire une demande de prêt, humaine ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "HORIZON_ACT5_INTERLUDE1@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3500501
L37_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_DESPAIR"
L37_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L37_1.m_Pos = "C"
L37_1.m_Crash = 10
L38_1 = "아뇨. 돈은 필요하지 않아요. 그런 것보다……."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "いいえ、お金は要りません。そんなものよりも……"
L37_1.m_Talk_JPN = L38_1
L38_1 = "No. I don't need money. I was actually hoping to ask…"
L37_1.m_Talk_ENG = L38_1
L38_1 = "沒有，我不需要錢，只是……"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ไม่ค่ะ ฉันไม่ต้องการเงิน จริงฉันแค่อยากจะถามว่า..."
L37_1.m_Talk_THA = L38_1
L38_1 = "Không, tôi không cần tiền. Tôi chỉ muốn hỏi…"
L37_1.m_Talk_VTN = L38_1
L38_1 = "不。我不需要钱。比起钱……"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Nein, ich brauche kein Geld. Was ich brauche, ist ..."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Non. Je n'ai pas besoin d'argent. Ce que je voulais vous demander c'est..."
L37_1.m_Talk_FRA = L38_1
