L41_1 = "HORIZON_ACT5_INTERLUDE1@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3500501
L40_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_Face = "UNIT_SERIOUS"
L40_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L40_1.m_Pos = "R"
L41_1 = "제가 호라이즌 씨를 따라가면…… 폐가 될까요?!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "私がホライズンさんについて行くのは……迷惑でしょうか？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Will I be a burden if I come with you?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "我跟你一起去的話……會妨礙你嗎？！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ถ้าฉันไปด้วยจะเป็นภาระมั้ยคะ?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Tôi sẽ là một gánh nặng nếu tôi đi cùng với cô phải không?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "地平线，如果我想和你一起……会对你造成困扰吗？！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Würde es Sie sehr stören, wenn ich mit Ihnen komme?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Si ça ne vous dérangeait pas que je vous accompagne...?"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "HORIZON_ACT5_INTERLUDE1@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3500501
L41_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L41_1.m_Pos = "L"
L42_1 = "네."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "はい。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Yes."
L41_1.m_Talk_ENG = L42_1
L42_1 = "會。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เป็นค่ะ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Phải."
L41_1.m_Talk_VTN = L42_1
L42_1 = "会。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ja."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Si."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "HORIZON_ACT5_INTERLUDE1@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3500501
L42_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "UNIT_HATE"
L42_1.m_Face = L43_1
L42_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L42_1.m_Pos = "R"
L42_1.m_Crash = 10
L43_1 = "읏, 그렇게 직설적으로 말씀하실 줄은 몰랐는데……."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ううっ、そんなストレートに断るなんて思わなかったのに……"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Aw… I didn't think you'd be so blunt about it…"
L42_1.m_Talk_ENG = L43_1
L43_1 = "喔，沒想到你會這麼直接地回答我……"
L42_1.m_Talk_TWN = L43_1
L43_1 = "โธ่... ไม่นึกว่าคุณจะตรงเปรี้ยงขนาดนี้..."
L42_1.m_Talk_THA = L43_1
L43_1 = "Aw… Tôi không nghĩ là cô lại thẳng thừng về điều đó thế…"
L42_1.m_Talk_VTN = L43_1
L43_1 = "呃，没想到你的回答这么直接……"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Oh ... ich habe nicht damit gerechnet, dass Sie so unverblümt antworten würden ..."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Oh... Je ne pensais pas que vous seriez aussi directe..."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "HORIZON_ACT5_INTERLUDE1@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3500501
L43_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L43_1.m_Pos = "L"
L44_1 = "당신은 저와 동행하기보다 건강을 관리하는 편을 추천드리고 싶군요."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "あなたには私との同行より、健康管理をおすすめします。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I would advise your time is better spent looking after your own health than accompanying me."
L43_1.m_Talk_ENG = L44_1
L44_1 = "你與其跟我去，倒不如先做好健康管理吧。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ขอแนะนำว่าคุณควรเอาเวลาไปดูแลสุขภาพมากกว่าไปกับฉันนะคะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi khuyên cô nên dành thời gian chăm sóc sức khỏe của chính mình hơn là đi cùng tôi."
L43_1.m_Talk_VTN = L44_1
L44_1 = "我觉得你应该先关心下自己的健康，而不是要不要和我同行。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich rate Ihnen, sich lieber um Ihre Gesundheit zu kümmern, als mich zu begleiten."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Je vous conseille d'éviter de perdre votre temps à m'accompagner, et de plutôt vous occuper de votre santé."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "HORIZON_ACT5_INTERLUDE1@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3500501
L44_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L44_1.m_Pos = "L"
L45_1 = "저는 유사시 당신에게 의료 서비스를 지원해 드릴 수 있는 기능이 없습니다."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "私には有事の際、あなたに医療サービスをサポートできる機能がありません。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I offer no features that can provide you medical support in an emergency."
L44_1.m_Talk_ENG = L45_1
L45_1 = "萬一發生什麼事，我沒有可以提供你急救服務的功能。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ถ้าเกิดเรื่องฉุกเฉินขึ้นมา ฉันไม่มีคุณลักษณะอะไรที่จะให้ความช่วยเหลือทางการแพทย์แก่คุณได้"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tôi không cung cấp tính năng nào có thể hỗ trợ y tế cho cô trong trường hợp khẩn cấp."
L44_1.m_Talk_VTN = L45_1
L45_1 = "我没有在遇到事情后给你提供医疗服务的功能。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ich verfüge über keine Funktionen, die Ihnen im Notfall medizinisch dienen könnten."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Je ne possède aucune capacité permettant d'apporter un quelconque support médical en cas d'urgence."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "HORIZON_ACT5_INTERLUDE1@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3500501
L45_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_SERIOUS"
L45_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L45_1.m_Pos = "R"
L45_1.m_Crash = 20
L46_1 = "저, 저도 싸움을 도와드릴 수 있어요!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "わ、私も戦闘ならお役に立てると思います！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I-I could help you fight!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "我…我也想助你一臂之力！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ฉะ-ฉันช่วยสู้ได้นะคะ!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Tôi có thể giúp cô chiến đấu!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "我、我也能帮你战斗！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "I-ich könnte Sie beim Kampf unterstützen!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "J-Je pourrais vous aider à vous battre !"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "HORIZON_ACT5_INTERLUDE1@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3500501
L46_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L46_1.m_Pos = "R"
L47_1 = "제가 아니라, 저를 지켜 주려는 아이들이 도와드리겠지만……. 없는 것보다는 나을 거에요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "正確には私ではなく、私を守ってくれる子たちのことですが……いないよりはきっとマシだと思います。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Well… I won't be doing the fighting, but the children who want to protect me will help… I'm sure it'll be better than nothing."
L46_1.m_Talk_ENG = L47_1
L47_1 = "不是我，而是這些保護我的孩子可以幫你……有總比沒有好吧？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "คือ... ฉันก็ไม่ได้สู้หรอกค่ะ แต่เด็กๆ ที่อยากปกป้องฉันจะช่วย... ฉันแน่ใจนะคะว่าดีกว่าไม่มีอะไรเลย"
L46_1.m_Talk_THA = L47_1
L47_1 = "Chà… Tôi sẽ không đánh nhau, nhưng bọn trẻ muốn bảo vệ tôi sẽ có ích… Tôi chắc rằng sẽ tốt hơn là không có gì."
L46_1.m_Talk_VTN = L47_1
L47_1 = "不是我，而是保护我的孩子们会帮你……总比没有要好。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Und wenn nicht ich, sondern die Kinder zur Unterstützung kommen würden ... es ist besser als nichts."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Enfin, je ne sais pas me battre à proprement parler, mais... Les enfants qui me protègent pourraient vous aider... C'est mieux que rien, non ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "HORIZON_ACT5_INTERLUDE1@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3500501
L47_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_DESPAIR"
L47_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L47_1.m_Pos = "L"
L48_1 = "하지만 교사로서 아이들을 인솔할 책임이 있지 않습니까?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "しかし、教師として子どもたちを引率する責任があるのではないですか？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "But are you not responsible for your students as their teacher?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "但身為一位老師，不是有責任要帶領孩子嗎？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "แต่คุณไม่ต้องรับผิดชอบเด็กๆ ในฐานะครูเหรอคะ?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Nhưng không phải cô có trách nhiệm với học sinh của mình với tư cách là giáo viên sao?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "但你作为教师不是需要履行照料孩子们的责任吗？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Aber als Lehrerin sind Sie für die Kinder verantwortlich, oder nicht?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "En tant que leur enseignante, n'est-ce pas votre rôle de vous occuper de vos élèves ?"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
