L49_1.m_Face = "UNIT_DESPAIR"
L49_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L49_1.m_Pos = "R"
L50_1 = "그 말이 맞아요. 하지만……."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "おっしゃるとおりです。ですが……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "True… But the thing is…"
L49_1.m_Talk_ENG = L50_1
L50_1 = "話是沒錯，可是……"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ก็จริงค่ะ... แต่เรื่อมันคือ..."
L49_1.m_Talk_THA = L50_1
L50_1 = "Đúng… Nhưng vấn đề là…"
L49_1.m_Talk_VTN = L50_1
L50_1 = "你说的对，但是……"
L49_1.m_Talk_SCN = L50_1
L50_1 = "D-das stimmt. Aber ..."
L49_1.m_Talk_DEU = L50_1
L50_1 = "C'est vrai, en effet. Mais..."
L49_1.m_Talk_FRA = L50_1
