L51_1 = "HORIZON_ACT5_INTERLUDE1@150#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 150
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3500501
L50_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L50_1.m_Pos = "R"
L51_1 = "사실은 저도, 저 아이들도……. 제프티 바이오테크에서 도망쳐 나온 신세니까요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "実は私も、あの子たちも……ジェフティ・バイオテックから逃げてきた身なんです。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "All those children and I… escaped from Jehuty Biotech."
L50_1.m_Talk_ENG = L51_1
L51_1 = "其實我，和那些孩子……我們都是從傑夫堤生物科技逃出來的。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "เด็กพวกนั้นทุกคนกับฉัน... หนีมาจากเจฮูตีไบโอเทคค่ะ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Tất cả những đứa trẻ đó và tôi… đã trốn thoát khỏi Jehuty Biotech."
L50_1.m_Talk_VTN = L51_1
L51_1 = "其实我，还有孩子们……都是从杰普提生物科技逃出来的。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Um ehrlich zu sein ... sind all diese Kinder und ich aus Jehuty Biotech geflüchtet."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Tous ces enfants, et moi-même... Nous nous sommes échappés de Jehuty Biotech."
L50_1.m_Talk_FRA = L51_1
