L4_1 = "HORIZON_ACT5_INTERLUDE1@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3500501
L3_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_IDLE"
L3_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L3_1.m_Pos = "C"
L4_1 = "굉장히 친절한 분을 만나서 지금은 이렇게 지내고 있지만……."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "とても親切な方に出会えて、今はこうやって平和に過ごしていますが……"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Although we were lucky enough to meet a kindred spirit to enjoy this comfort…"
L3_1.m_Talk_ENG = L4_1
L4_1 = "雖然遇到一位非常好心的人，我們才可以像現在這樣……"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ถึงเราจะโชคดีพอได้เจอคนที่เป็นเหมือนพี่น้องมาอยู่กันอย่างสบายใจแบบนี้..."
L3_1.m_Talk_THA = L4_1
L4_1 = "Mặc dù chúng tôi đã may mắn gặp được một người tốt bụng để tận hưởng sự thoải mái này…"
L3_1.m_Talk_VTN = L4_1
L4_1 = "虽然遇到了非常亲切的人，可以拥有现在这样生活……"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Wir hatten das Glück, eine herzensgute Person zu treffen und im Komfort zu leben, aber ..."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Nous avons eu de la chance de rencontrer une âme charitable qui nous a permis de vivre la vie que nous vivons actuellement..."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "HORIZON_ACT5_INTERLUDE1@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3500501
L4_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Face = "UNIT_SERIOUS"
L4_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L4_1.m_Pos = "C"
L4_1.m_Crash = 5
L5_1 = "저는, 저 아이들이, 그리고 저처럼 실험체로 쓰였던 아이들이 겪었던 일을……."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "私はあの子たちが、そして私と同じく実験体として使われた子たちが経験したことを……"
L4_1.m_Talk_JPN = L5_1
L5_1 = "I have never forgotten what children like them and me had to endure as test subjects…"
L4_1.m_Talk_ENG = L5_1
L5_1 = "但我和這些孩子，還有那些和我一樣成為實驗體的孩子……"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แต่ฉันก็ไม่เคยลืมนะคะว่าเด็กๆ อย่างพวกเขากับฉันต้องเคยทนเป็นตัวทดลองมาก่อน..."
L4_1.m_Talk_THA = L5_1
L5_1 = "Tôi chưa bao giờ quên những đứa trẻ như chúng và tôi đã phải chịu đựng khi trở thành vật thí nghiệm…"
L4_1.m_Talk_VTN = L5_1
L5_1 = "但我没办法忘记，没办法忘记像我一样被当作实验体的孩子们"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Ich habe nie vergessen, was diese Kinder und ich als Testsubjekt ertragen mussten ..."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Mais je n'ai jamais oublié ce que nous avons du endurer en tant que cobayes..."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "HORIZON_ACT5_INTERLUDE1@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3500501
L5_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L5_1.m_Pos = "C"
L5_1.m_Crash = 20
L6_1 = "한 순간도 잊은 적이 없어요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "一度も忘れたことがありません。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Not for a single moment."
L5_1.m_Talk_ENG = L6_1
L6_1 = "從未忘記過我們經歷過的事。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ไม่เคยลืมสักวินาทีเลยค่ะ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Không một giây phút nào."
L5_1.m_Talk_VTN = L6_1
L6_1 = "经受过的摧残……"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Nicht einen einzigen Augenblick."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Cela restera gravé en moi à jamais."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "HORIZON_ACT5_INTERLUDE1@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3500501
L6_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_IDLE"
L6_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L6_1.m_Pos = "C"
L7_1 = "알고 있었습니다. 당신들의 생체 정보가 연구 시설 데이터베이스에 존재했으니까요."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "それは認知していました。あなたたちの生体情報は研究施設のデータベースに存在していました。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "I am already aware of that. Your biometric data was stored in the research facility's database."
L6_1.m_Talk_ENG = L7_1
L7_1 = "我知道，研究設施的資料庫裡有你們的生物資訊。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ฉันทราบเรื่องนั้นแล้วค่ะ มีข้อมูลชีวมาตรของคุณอยู่ในฐานข้อมูลของศูนย์วิจัย"
L6_1.m_Talk_THA = L7_1
L7_1 = "Tôi đã biết được điều đó. Dữ liệu sinh trắc học của cô đã được lưu trữ trong cơ sở dữ liệu của cơ sở nghiên cứu."
L6_1.m_Talk_VTN = L7_1
L7_1 = "我早就知道了。因为你们的生物信息还存在于研究设施的数据库当中。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ich weiß das bereits. Ihre biometrischen Daten waren in der Datenbank der Forschungseinrichtung gespeichert."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Je suis déjà au courant de tout cela. Vos données biométriques étaient enregistrées dans la base de données du centre de recherche."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "HORIZON_ACT5_INTERLUDE1@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3500501
L7_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L7_1.m_Pos = "C"
L8_1 = "그래서, 당신은 제프티 바이오테크에 복수하고 싶습니까."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "それで、あなたはジェフティ・バイオテックに復讐したいのですか。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "So, is it revenge you seek against Jehuty Biotech?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "意思是，你想向傑夫堤生物科技報仇嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ถ้าอย่างนั้น คุณอยากแก้แค้นเจฮูตีไบโอเทคเหรอคะ?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Vì vậy, có phải là cô muốn trả thù Jehuty Biotech không?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "所以，你想对杰普提生物科技复仇吗？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Sie möchten Sich also an Jehuty Biotech rächen?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Vous souhaitez donc vous venger de Jehuty Biotech ?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "HORIZON_ACT5_INTERLUDE1@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3500501
L8_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_DESPAIR"
L8_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L8_1.m_Pos = "C"
L9_1 = "……네. 저 아이들은 아무것도 몰랐으면 하니까요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "……はい。あの子たちには、ずっと知らないままでいてほしいからです。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "…Yes. Because I hope those kids never have to find out."
L8_1.m_Talk_ENG = L9_1
L9_1 = "……是，因為我不希望孩子們知道這些事。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "... ค่ะ เพราะฉันหวังว่าเด็กพวกนี้จะได้ไม่ต้องมารับรู้"
L8_1.m_Talk_THA = L9_1
L9_1 = "…Phải. Vì tôi hy vọng những đứa trẻ đó không bao giờ biết."
L8_1.m_Talk_VTN = L9_1
L9_1 = "……是的。但是我不希望那些孩子们知道真相。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ja ... Weil ich hoffe, dass diese Kinder nie etwas darüber erfahren müssen."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Oui... Parce que je veux protéger les enfants..."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "HORIZON_ACT5_INTERLUDE1@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3500501
L9_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L9_1.m_Pos = "C"
L10_1 = "저 아이들이 더 세상을 알기 전에, 그래서 언젠가 자기들이 얼마나 끔찍한 일을 겪었는지 알게 되기 전에……."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "あの子たちが世の中を知っていく前に、\nいつか自分たちがどれほどひどい目にあっていたのか気づく前に……"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Before those children learn more about the world and in turn realize what horrors were done to them…"
L9_1.m_Talk_ENG = L10_1
L10_1 = "在孩子們更認識世界之前，在他們發現原來經歷過那麼可怕的事之前……"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ก่อนที่เด็กพวกนี้จะรู้จักโลกมากขึ้น และได้รู้ว่าตัวเองเจอเรื่องโหดร้ายขนาดไหนมา..."
L9_1.m_Talk_THA = L10_1
L10_1 = "Trước khi những đứa trẻ đó hiểu thêm về thế giới và lần lượt nhận ra điều kinh hoàng đã gây ra cho chúng…"
L9_1.m_Talk_VTN = L10_1
L10_1 = "在那些孩子们了解这个世界之前，在他们认识到自己经受过多么残忍的摧残之前……"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Bevor sie mehr über die Welt erfahren und begreifen, was ihnen angetan wurde ..."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Je veux les protéger avant qu'ils n'en apprennent davantage sur ce monde, et sur les horreurs qu'on leur a fait subir..."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "HORIZON_ACT5_INTERLUDE1@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3500501
L10_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_SERIOUS"
L10_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L10_1.m_Pos = "C"
L11_1 = "없어졌으면 좋겠어요. 저 아이들이 평생 동안 누군가를 미워하고 원망하지 않게."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "あの会社は無くなってほしいんです。あの子たちが一生誰かを憎み恨まないためにも。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "I hope Jehuty gets wiped off the planet. So those children won't end up spending their entire lives despising someone."
L10_1.m_Talk_ENG = L11_1
L11_1 = "我希望可以先弭平這件事，讓孩子們不要一輩子都在怨恨中度過。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ฉันหวังว่าเจฮูตีจะถูกกวาดล้างไปจากโลกนี้ค่ะ เด็กพวกนั้นจะได้ไม่ต้องลงเอยด้วยการใช้ทั้งชีวิตไปกับการชิงชังใคร"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tôi hy vọng Jehuty sẽ bị xóa sổ khỏi hành tinh. Để những đứa trẻ đó sẽ không phải dành cả đời để căm hận ai đó."
L10_1.m_Talk_VTN = L11_1
L11_1 = "消灭掉那些人。希望孩子们不会一辈子都在憎恨和埋怨别人。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "sollte Jehuty aus der Welt verschwinden. Damit diese Kinder nicht ihr ganzes Leben damit verbringen müssen, jemanden zu hassen und zu verachten."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Je veux réduire Jehuty Biotech en cendres, afin d'éviter que les enfants ne passent leur vie à les haïr."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "HORIZON_ACT5_INTERLUDE1@161#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3500501
L11_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_IDLE"
L11_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L11_1.m_Pos = "C"
L12_1 = "그렇다면 당신은 저와 함께할 수 없습니다. 휴먼."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "そのような理由なら、あなたは私と同行することはできません、ヒューマン。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "That's all the more reason why you cannot accompany me, human."
L11_1.m_Talk_ENG = L12_1
L12_1 = "那你更不能與我同行，人類。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "นั่นก็เป็นเหตุผลที่มากเพียงว่าทำไมคุณถึงไปกับฉันไม่ได้แล้วค่ะมนุษย์"
L11_1.m_Talk_THA = L12_1
L12_1 = "Đó là tất cả những lý do tại sao cô không thể đi cùng tôi, con người."
L11_1.m_Talk_VTN = L12_1
L12_1 = "如果是这样，你不能和我在一起。人类。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Dann können Sie nicht mit mir kommen, Mensch."
L11_1.m_Talk_DEU = L12_1
L12_1 = "C'est d'autant plus de raisons qui font que vous ne pouvez pas m'accompagner, humaine."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "HORIZON_ACT5_INTERLUDE1@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3500501
L12_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_SURPRISE"
L12_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L12_1.m_Pos = "C"
L12_1.m_Crash = 15
L13_1 = "네……? 어, 어째서요?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "はい……？　ど、どうしてですか？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Sorry…? H-how come?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "嗯……？為什麼？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "อะไรนะคะ...? ทะ-ทำไมล่ะ?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Xin lỗi…? S-sao lại thế?"
L12_1.m_Talk_VTN = L13_1
L13_1 = "啊……？为、为什么？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Huch ...? Wieso nicht?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Pardon...? M-Mais pourquoi ?"
L12_1.m_Talk_FRA = L13_1
