L16_1 = "HORIZON_ACT5_INTERLUDE1@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 3500501
L15_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_DESPAIR"
L15_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L15_1.m_Pos = "L"
L16_1 = "당신은 복수를 원한 적이 없습니다. 저 아이들을 세상으로부터 지켜 주고 싶을 뿐이죠."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "あなたは復讐を望んでいません。あの子たちをこの世の中から守ってあげたいだけです。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "You never truly wanted revenge. All you desire is to shelter those children from the world."
L15_1.m_Talk_ENG = L16_1
L16_1 = "因為你並不是想報仇，你只是想保護那些孩子而已。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "คุณไม่ได้อยากแก้แค้นจริงๆ ซะหน่อยค่ะ ที่คุณต้องการคือกันเด็กพวกนั้นให้พ้นจากโลก"
L15_1.m_Talk_THA = L16_1
L16_1 = "Cô chưa bao giờ thực sự muốn trả thù. Tất cả những gì cô mong muốn là che chở những đứa trẻ đó khỏi thế giới."
L15_1.m_Talk_VTN = L16_1
L16_1 = "因为你从来没想过要复仇。你只是想保护孩子们不受到世间的伤害。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Sie wollten nie Rache. Sie wollen nur diese Kinder vor der Welt beschützen."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Vous ne cherchez pas à vous venger. Tout ce que vous désirez, c'est de protéger les enfants contre les aléas du monde."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "HORIZON_ACT5_INTERLUDE1@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3500501
L16_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L16_1.m_Pos = "L"
L17_1 = "아이들은 행복해 보이더군요. 당신은 지금의 삶이 행복합니까?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "子どもたちは幸せそうでしたね。あなたは今の人生が幸せですか？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "The children seemed happy enough. But are you happy with your current life?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "孩子們現在看起來很幸福，那你現在幸福嗎？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "เด็กพวกนั้นดูมีความสุขดีแล้วนะคะ แต่คุณละคะ ตอนนี้มีความสุขกับชีวิตตัวเองดีหรือเปล่า?"
L16_1.m_Talk_THA = L17_1
L17_1 = "Những đứa trẻ dường như đã đủ hạnh phúc. Nhưng cô có hài lòng với cuộc sống hiện tại của mình không?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "孩子们看起来很快乐。你觉得现在的生活幸福吗？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Die Kinder sehen glücklich aus. Und Sie? Sind Sie glücklich?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Les enfants ont l'air relativement heureux. Mais, et vous ? Êtes-vous satisfaite de votre vie actuelle ?"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "HORIZON_ACT5_INTERLUDE1@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3500501
L17_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_DESPAIR"
L17_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L17_1.m_Pos = "R"
L17_1.m_Crash = 10
L18_1 = "…………네. 하루하루가 무척, 행복하고 소중해요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "……はい。毎日がとても幸せで、大切です。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "…Yes. Every moment is so precious and filled with joy."
L17_1.m_Talk_ENG = L18_1
L18_1 = "…………是，我每一天都非常幸福。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "... มีสิคะ ทุกช่วงเวลาทั้งมีค่าและเปี่ยมสุข"
L17_1.m_Talk_THA = L18_1
L18_1 = "…Vâng. Mỗi giây phút đều thật quý giá và tràn ngập niềm vui."
L17_1.m_Talk_VTN = L18_1
L18_1 = "……是的。我觉得每天都非常幸福和珍贵！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ja ... Jeder Moment ist so kostbar und voller Freude."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Oui... Mes journées sont emplies de bonheur et d'instants tous aussi précieux les uns que les autres."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "HORIZON_ACT5_INTERLUDE1@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3500501
L18_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L18_1.m_Pos = "L"
L19_1 = "그렇다면 그 시간을 저 아이들과 더 많이 나눠 주십시오."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "ならばその時間を、あの子たちにもっとたくさん分けてあげてください。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Then spend your time sharing that delight with those children."
L18_1.m_Talk_ENG = L19_1
L19_1 = "這樣的話，那你還是把時間花在和孩子們相處上吧"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ถ้าอย่างนั้นก็ใช้ชีวิตอย่างมีความสุขร่วมกับเด็กๆ ไปค่ะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Vậy hãy dành thời gian chia sẻ niềm vui với những đứa trẻ đó."
L18_1.m_Talk_VTN = L19_1
L19_1 = "那么你就和孩子们享受更多幸福的时间吧。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Dann verbringen Sie Ihre Zeit damit, diese Freude mit diesen Kindern zu teilen."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Dans ce cas, vous devriez accorder votre temps à ces enfants."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "HORIZON_ACT5_INTERLUDE1@169#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 169
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 3500501
L19_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L19_1.m_Pos = "L"
L20_1 = "시간은 귀중한 재화입니다. 그리고 재화가 많은 휴먼은 대부분 행복해하더군요."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "時間は貴重な財貨です。そしてその財貨が多いヒューマンほど、幸せそうに暮らしていました。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Time is a precious commodity. Most humans plentiful in commodities seem to be happy."
L19_1.m_Talk_ENG = L20_1
L20_1 = "時間是非常寶貴的資產，而資產多的人類通常都是幸福的。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "เวลาเป็นสินค้าโภคภัณฑ์ที่มีค่านะคะ มนุษย์ที่มีสินค้าโภคภัณฑ์เหลือเฟือดูมีความสุขดีค่ะ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Thời gian là một thứ hàng hóa quý giá. Hầu hết người dồi dào hàng hóa dường như đều hạnh phúc."
L19_1.m_Talk_VTN = L20_1
L20_1 = "时间是很宝贵的财产，而拥有大量财产的人类大多都是幸福的。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Zeit ist ein kostbares Gut. Außerdem scheinen die meisten Menschen, die reich an Ressourcen sind, glücklich zu sein."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Le temps vaut tout l'or du monde. Et les humains riches semblent heureux, pour la plupart."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 3500501
L20_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L20_1.m_bWaitClick = false
L20_1.m_fWaitTime = 0
L20_1.m_bClear = true
L21_1 = {}
L22_1 = "HORIZON_ACT5_INTERLUDE1@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3500501
L21_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "UNIT_HATE"
L21_1.m_Face = L22_1
L21_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "당신은 당신의 적들도 연민하고 괴로워할 휴먼입니다."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "あなたは自分の敵でさえ憐憫の情を覚えるヒューマンです。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "You are someone who would sympathize with and mourn over your enemies."
L21_1.m_Talk_ENG = L22_1
L22_1 = "你是會為敵人感到可憐和傷心的人類。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "คุณเป็นคนแบบที่จะเห็นอกเห็นใจและเสียใจให้ศัตรูของตัวเอง"
L21_1.m_Talk_THA = L22_1
L22_1 = "Cô là người có thể thông cảm và thương xót cho kẻ thù của mình."
L21_1.m_Talk_VTN = L22_1
L22_1 = "你是连自己的敌人也会怜悯，并为之苦恼的人类。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Sie sind ein Mensch, der tief gefühltes Mitleid mit seinen Feinden haben würde."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Vous avez l'air d'être quelqu'un capable de sympathiser avec ses ennemis, et même pleurer leur mort."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "HORIZON_ACT5_INTERLUDE1@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3500501
L22_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L22_1.m_Pos = "C"
L23_1 = "고통을 자처하느라 저 아이들에게 나눠 줄 행복도 허비하지 마십시오."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "自らの苦悶のために、あの子たちに与える幸せまで無駄にしないでください。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Do not squander the happiness you can share with those children by insisting on bringing suffering upon yourself."
L22_1.m_Talk_ENG = L23_1
L23_1 = "為何要自討苦吃，而浪費掉可以和孩子們相處的幸福時間？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "อย่าเอาความสุขที่มีร่วมกับเด็กพวกนั้นได้มาใช้\nอย่างสุรุ่ยสุร่ายด้วยการดึงดันจะหาความทุกข์ทรมานใส่ตัวเลยค่ะ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Đừng phung phí hạnh phúc mà cô có thể chia sẻ với những đứa trẻ đó bằng cách cố chấp tự chuốc lấy đau khổ cho mình."
L22_1.m_Talk_VTN = L23_1
L23_1 = "别因为自寻苦恼，浪费掉该分享给孩子们的幸福。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Begehen Sie nicht den Fehler, das Glück zu vergeuden, das diesen Kindern zusteht."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Ne gâchez pas cette chance que vous avez de pouvoir vivre une vie heureuse en compagnie de ces enfants en vous mettant dans une situation périlleuse."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
