L25_1 = "HORIZON_ACT5_INTERLUDE1@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3500501
L24_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L24_1.m_Pos = "C"
L25_1 = "저는 이만 떠날 예정입니다, 휴먼."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "私はそろそろここを発ちます、ヒューマン。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "I will leave presently, human."
L24_1.m_Talk_ENG = L25_1
L25_1 = "我要走了，人類。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ฉันจะไปแล้วนะคะมนุษย์"
L24_1.m_Talk_THA = L25_1
L25_1 = "Tôi sẽ rời đi ngay bây giờ, con người."
L24_1.m_Talk_VTN = L25_1
L25_1 = "我现在该离开了，人类。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Ich werde jetzt aufbrechen, Mensch."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Je vais m'en aller incessamment sous peu, humaine."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "HORIZON_ACT5_INTERLUDE1@175#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 175
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3500501
L25_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "그래도 당신들 덕분에 방법론을 수정할 기회가 생겼으니, 무작정 막지는 않겠습니다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "ですが、あなたたちのおかげで方法論を修正する機会ができたので、むやみに止めることはしません。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "But as I have gained the chance to modify my methodology thanks to you, I won't stop you from joining me."
L25_1.m_Talk_ENG = L26_1
L26_1 = "不過托你們的福，讓我有修改方法論的機會，所以我不會一昧地阻止你。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "แต่ในเมื่อฉันมีโอกาสได้ดัดแปลงกระบวนกระบวนวิธีของตัวเองเพราะคุณ ฉันจะไม่ห้ามค่ะถ้าคุณจะมาด้วย"
L25_1.m_Talk_THA = L26_1
L26_1 = "Nhưng vì tôi đã có cơ hội sửa đổi phương pháp luận của mình nhờ cô, tôi sẽ không ngăn cản cô tham gia cùng tôi."
L25_1.m_Talk_VTN = L26_1
L26_1 = "但也多亏了你们我才有机会修改我的运算方法，所以我不会盲目反对。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Doch dank Ihnen erhielt ich die Möglichkeit, meine Methodik zu ändern. Also werde ich Sie nicht daran hindern, sich mir anzuschließen."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Mais puisque j'ai eu la chance de modifier ma méthodologie grâce à vous, je ne ferai rien pour vous empêcher de me suivre."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "HORIZON_ACT5_INTERLUDE1@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3500501
L26_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "피 묻은 손으로 아이들을 안을 자신이 있다면, 절 건져 온 침식체를 다시 불러와서 동행하시죠."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "血に染まった手であの子たちを抱きしめる覚悟があるなら、私を引き揚げた侵食体とともに同行しても構いません。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "If you are confident you will not regret holding those children with bloodstained hands, you may join me alongside that C.O. who plucked me out of the water."
L26_1.m_Talk_ENG = L27_1
L27_1 = "如果你確定，你能用沾滿鮮血的雙手擁抱孩子們，那就再次召喚那個把我打撈起來的侵蝕體，和我一起走吧。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ถ้าคุณไม่เสียใจว่าจะต้องกอดเด็กๆ พวกนั้นด้วยมือที่เปื้อนเลือด คุณก็กับวัตถุคอร์รัปต์ที่ดึงฉันขึ้นมาจากน้ำนั้นก็มาด้วยกันได้ค่ะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Nếu cô tự tin rằng mình sẽ không hối hận vì sẽ ôm những đứa trẻ với bàn tay nhuốm máu, cô có thể tham gia cùng tôi cùng với V.T.A.M. mà đã vớt tôi lên khỏi mặt nước."
L26_1.m_Talk_VTN = L27_1
L27_1 = "如果你有自信用沾满鲜血的手去拥抱孩子们的话，可以叫上把我打捞起来的侵蚀体与我同行。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Wenn Sie diese Kinder mit blutbefleckten Händen umarmen können, dann rufen Sie das C.°O. wieder herbei, das mich geborgen hat, und kommen Sie mit."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Si vous êtes bien sûre que vous ne regretterez pas d'avoir du sang sur les mains lorsque vous enlacerez les enfants, vous pouvez vous joindre à moi. Vous et cet Objet Corrompu qui m'a sortie de l'eau."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
