L29_1.m_Face = "UNIT_DESPAIR"
L29_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L29_1.m_Pos = "C"
L30_1 = "미안해요. 호라이즌 씨."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "すみません、ホライズンさん。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I'm sorry… Ms. Horizon."
L29_1.m_Talk_ENG = L30_1
L30_1 = "地平線小姐，很抱歉……"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ขอโทษนะคะ... คุณฮอไรซัน"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi xin lỗi… Cô Horizon."
L29_1.m_Talk_VTN = L30_1
L30_1 = "对不起。地平线小姐。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Tut mir leid, Miss Horizon."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Désolée, Horizon..."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "HORIZON_ACT5_INTERLUDE1@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3500501
L30_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "LUCID_BARCODE_NULL_NULL"
L30_1.m_Pos = "C"
L31_1 = "저도 조금은…… 이기적인가 봐요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "私も少し……わがままを言ったようです。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I'm afraid… I'm rather selfish."
L30_1.m_Talk_ENG = L31_1
L31_1 = "我可能……也是自私的。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เกรงว่า... ฉันจะเห็นแก่ตัวไปหน่อย"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi sợ ... tôi khá ích kỷ."
L30_1.m_Talk_VTN = L31_1
L31_1 = "看来我也……很自私。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich fürchte, ich bin ziemlich egoistisch."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je crois que je suis pour le moins... égoïste."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
