L37_1 = "HORIZON_ACT5_INTERLUDE1@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3500501
L36_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "NCSC_STOP"
L36_1.m_StartFXSoundControl = L37_1
L37_1 = "FX_CUTSCEN_NOISE_RUSTLE"
L36_1.m_StartFXSoundName = L37_1
L37_1 = "RYAN_PRYDWEN_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "R"
L37_1 = "아가씨, 손님이 배에서 내리셨습니다. 수영으로 육지까지 갈 작정이더군요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "お嬢様、お客様が船から降りました。泳いで陸地まで向かうようです。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "My Lady, the guest has disembarked the ship. It appears she plans to swim ashore."
L36_1.m_Talk_ENG = L37_1
L37_1 = "小姐，客人下船了，看來她是打算用游的游上岸。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ท่านหญิง แขกลงจากเรือไปแล้วครับ ดุเหมือนเธอตั้งใจจะว่ายไปถึงฝั่งนะครับ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Thưa cô, vị khách đã xuống tàu. Có vẻ như cô ấy định bơi vào bờ."
L36_1.m_Talk_VTN = L37_1
L37_1 = "小姐。顾客下船了。好像打算要游到陆地去。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Fräulein, der Gast hat das Schiff verlassen. Sie scheint bis an Land schwimmen zu wollen."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Mademoiselle, notre invitée a quitté le navire. Il semblerait qu'elle ai décidé de rejoindre la terre ferme à la nage."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "HORIZON_ACT5_INTERLUDE1@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3500501
L37_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "L"
L38_1 = "그래요. 저희는 조금 더 바닷바람을 즐기다 출발하기로 하죠."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "そうですか。私たちはもう少し潮風を楽しんでから出発することにしましょう。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I see. Let us enjoy the ocean breeze for few more minutes before we depart."
L37_1.m_Talk_ENG = L38_1
L38_1 = "是嗎？那我們就再吹一下海風再出發吧。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "อย่างนั้นหรือนี่ เราก็รับลมทะเลกันอีกนิดก่อนจะออกเรือเถอะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tôi hiểu rồi. Hãy để chúng ta tận hưởng làn gió biển trong vài phút nữa trước khi khởi hành."
L37_1.m_Talk_VTN = L38_1
L38_1 = "是嘛。那我们就享受下海风后再重新出发吧。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Verstehe. Lassen Sie uns die Meeresbrise genießen, bevor wir aufbrechen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Je vois. Laissez-nous profiter encore un peu de la brise marine avant de partir."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "HORIZON_ACT5_INTERLUDE1@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3500501
L38_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_DESPAIR"
L39_1 = "RYAN_PRYDWEN_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "R"
L39_1 = "하지만…… 정말 정보를 넘겨 주셔도 괜찮으시겠습니까?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "しかし……本当に情報を渡してもよかったのでしょうか？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "But… Are you sure you want to turn over all the information?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "不過……把情報透漏給她真的沒問題嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แต่... คุณแน่ใจเหรอครับว่าส่งมอบข้อมูลทั้งหมดนั่น"
L38_1.m_Talk_THA = L39_1
L39_1 = "Nhưng… Cô có chắc chắn muốn lật lại tất cả thông tin không?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "可是……直接将情报给她，真的没关系吗？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Aber sind Sie sicher, dass Sie die Informationen weitergeben möchten?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Mais... Êtes-vous sûre de vouloir transférer nos informations ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "HORIZON_ACT5_INTERLUDE1@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3500501
L39_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "RYAN_PRYDWEN_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "R"
L40_1 = "배에 적재되어 있던 이터니움을 모두 투입해도 2% 남짓한 동력에 불과했습니다."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "船に積載されていたエタニウムをすべて投入しても、2%弱の動力にしかなりませんでした。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "We used an entire shipload of Eternium to charge her, but that amounted to merely 2% of total power at most."
L39_1.m_Talk_ENG = L40_1
L40_1 = "就算投入船上所有的永恆之金，動能也不過就區區2%而已。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "คือเราใช้อีเทอร์เนียมทั้งหมดที่มีชาร์จพลังให้เธอ แต่ชาร์จได้สูงสุดแค่ 2% เท่านั้น"
L39_1.m_Talk_THA = L40_1
L40_1 = "Chúng ta đã sử dụng toàn bộ lượng Vàng Vĩnh Cửu trên tàu để sạc cho cô ấy, nhưng con số đó chỉ chiếm tối đa 2% tổng sức mạnh."
L39_1.m_Talk_VTN = L40_1
L40_1 = "将船上装的所有能晶都投入后，也仅仅恢复了她2%左右的动力而已。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Obwohl wir eine ganze Schiffsladung Eternium verbraucht haben, um sie aufzuladen, haben wir nur etwa 2 % der Gesamtenergie erreicht."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Nous avons utilisé une cargaison entière d'éternium, mais cela aura à peine servi à recharger 2 % de son énergie totale."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "HORIZON_ACT5_INTERLUDE1@190#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 190
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3500501
L40_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "RYAN_PRYDWEN_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "R"
L41_1 = "자칫 길을 잘못 들었다간 상황이 곤란해질지도 모릅니다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "ともすれば困難な状況になるかもしれません。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "We may put ourselves in a difficult position if we do not tread carefully."
L40_1.m_Talk_ENG = L41_1
L41_1 = "萬一出什麼差錯，情況可能會變得很艱難。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ถ้าทำอะไรไม่ระวัง เราจะตกที่นั่งลำบากเอาได้นะครับ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Chúng ta có thể tự đặt mình vào tình thế khó khăn nếu không bước đi cẩn thận."
L40_1.m_Talk_VTN = L41_1
L41_1 = "如果一不小心，可能会让情况变得糟糕。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Wenn es schiefläuft, könnte es schlecht für uns aussehen."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Nous pourrions nous mettre dans une situation plus que délicate si nous ne faisons pas attention."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "HORIZON_ACT5_INTERLUDE1@191#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3500501
L41_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "L"
L42_1 = "믿어 보기로 하죠. 자신의 한계를 안다는 것이 기계의 장점이니까요."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "信じてみましょう。自身の限界を知っていることが機械の長所ですから。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Let's give her the benefit of the doubt for now. After all, the greatest strength of machines lies in their ability to know their limits."
L41_1.m_Talk_ENG = L42_1
L42_1 = "就相信她吧。機器人最大的優點，就是清楚自己的極限到哪裡。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ก็ถือว่ายกประโยชน์ให้จำเลยไปก่อนแล้วกัน เพราะถึงยังไง จุดแข็งที่สำคัญที่สุดของจักรกลก็คือความสามารถที่จะรู้ขีดจำกัดของตัวเองไงล่ะ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Hãy cho cô ấy lợi ích của sự nghi ngờ bây giờ. Suy cho cùng, sức mạnh lớn nhất của máy móc nằm ở khả năng biết được giới hạn của chúng."
L41_1.m_Talk_VTN = L42_1
L42_1 = "我选择相信她。因为机械的优点在于清楚自己的极限。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Vertrauen wir ihr mal. Der Vorteil von Maschinen ist, dass sie wissen, wo ihre Grenzen liegen."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Donnons-lui le bénéfice du doute, pour l'instant. Après tout, la plus grande force des machines c'est de connaître leurs limites."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
