L45_1 = "HORIZON_ACT5_INTERLUDE1@194#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 194
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3500501
L44_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "가기 전에, 한 가지 요청드리겠습니다. 정보료는 추후 청구하십시오."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "発つ前に、1点要請があります。情報料は後日請求してください。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I have one request to make before I depart. You may bill me later for the information."
L44_1.m_Talk_ENG = L45_1
L45_1 = "離開前我有件要麻煩你，請之後再跟我請款索取情報的費用。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ก่อนไปฉันมีเรื่องอย่างหนึ่งที่อยากขอค่ะ คุณส่งบิลมาเรียกเก็บค่าข้อมูลทีหลังได้นะคะ"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tôi có một yêu cầu phải thực hiện trước khi đi. Cô có thể lập hóa đơn cho tôi sau để biết thông tin."
L44_1.m_Talk_VTN = L45_1
L45_1 = "在走之前，我想请求一件事。请事后再收取情报费。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ich habe eine Bitte, bevor ich abreise. Stellen Sie mir die Informationen später in Rechnung."
L44_1.m_Talk_DEU = L45_1
L45_1 = "J'ai une demande à vous faire avant de partir. Vous pouvez me facturer plus tard pour ces informations."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "HORIZON_ACT5_INTERLUDE1@195#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 195
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3500501
L45_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "HORIZON_HORIZON_NULL_NULL"
L45_1.m_Pos = "C"
L46_1 = "제프티 바이오테크가 소유한 연구 시설들의 위치를 희망합니다."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "ジェフティ・バイオテックが所有する研究施設の位置情報を希望します。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I wish to know the locations of research facilities owned by Jehuty Biotech."
L45_1.m_Talk_ENG = L46_1
L46_1 = "我想知道傑夫堤生物科技所有研究設施的位置。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ฉันอยากรู้ตำแหน่งศูนย์วิจัยที่ต่างๆ ของเจฮูตีไบโอเทคค่ะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Tôi muốn biết vị trí của các cơ sở nghiên cứu thuộc sở hữu của Jehuty Biotech."
L45_1.m_Talk_VTN = L46_1
L46_1 = "我希望得到杰普提生物科技拥有的研究设施位置。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Ich beantrage, die Positionen der Forschungseinrichtungen von Jehuty Biotech zu erhalten."
L45_1.m_Talk_DEU = L46_1
L46_1 = "J'aimerais connaître l'emplacement des centres de recherches de Jehuty Biotech."
L45_1.m_Talk_FRA = L46_1
