L48_1.m_Face = "UNIT_LAUGH"
L49_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "……솔직하지 못한 로봇이라."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "……素直になれないロボットですか。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "…A dishonest robot, huh."
L48_1.m_Talk_ENG = L49_1
L49_1 = "……真是不坦率的機器人。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "... เป็นหุ่นยนต์ที่ปากไม่ตรงกับใจนะ"
L48_1.m_Talk_THA = L49_1
L49_1 = "… Một người máy không trung thực, huh."
L48_1.m_Talk_VTN = L49_1
L49_1 = "……真是个不够坦率的机器人。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ein unehrlicher Roboter ..."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Un robot malhonnête, hein..."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "HORIZON_ACT5_INTERLUDE1@199#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 199
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3500501
L49_1.m_CutScenStrID = "HORIZON_ACT5_INTERLUDE1"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "ELIZABETH_PRYDWEN_NULL_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "한 번쯤은 오래된 목소리도 실수를 하길 기대하고 있었는데, 아쉽게 됐어요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "一度くらいは古き声が過ちを犯すことを楽しみにしていましたが、残念でしたわ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I was hoping the Old Voice would make a mistake for a change. Too bad."
L49_1.m_Talk_ENG = L50_1
L50_1 = "原本還期待老聲音起碼可以出一次錯的，真可惜。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "นึกว่าเสียงอดีตจะทำพลาดซะอีก แย่จัง"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tôi đã hy vọng Old Voice sẽ mắc sai lầm để có sự thay đổi. Quá tệ."
L49_1.m_Talk_VTN = L50_1
L50_1 = "本来期待着老朋友至少会有一次失误，但真可惜。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Ich hatte gehofft, dass die Alte Stimme zur Abwechslung mal falsch liegen würde. Schade."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Moi qui espérais que pour une fois, l'ancienne voix se serait trompée. Pas de chance."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
